(window.STORIES=window.STORIES||[]).push(...[{"n": 72, "l": "الجزء 46 | بداية هجرة رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السادسة_والأربعون\n#بداية_هجرة_رسول_الله\nاتكلمنا عن بيعة العقبة الثانية وإزاي الأنصار بدأوا يُهيؤوا يثرب لاستقبال رسول الله ﷺ و المسلمين  إللي هيهاجروا، وشوفنا فعلا أعداد من الصحابة هاجروا ليثرب ، وكان لما المسلمين بيوصلوا ليثرب كان بيستقبلهم الأنصار ويضيفوهم ويراعوهم ، \nكل واحد ياخد إللي يقدر عليه من المسلمين المهاجرين من مكة، إللي ياخد له رجل وإللي ياخد له اثنين، كل واحد وإللي يقدر عليه\n \nكل يوم قريش تصحى الصبح يلاقوا واحد منهم اختفى، يلاقوا عيلة كاملة اختفت، الناس دي بتروح فين\nهم كانوا عارفين من موسم الحج إن أهل يثرب لهم علاقة بالموضوع، لكنهم مش متأكدين أوي ومش فاهمين إيه إللي بيحصل بالضبط\nفبدأت تأتي لهم أخبار من يثرب من معارف لهم هناك إن المسلمين بيهاجروا إلى يثرب،\nفالموضوع ده عمل لهم قلق، المسلمين بدأ يكون لهم مكان هيستقروا ويتجمعوا فيه،\nوده إللي قريش مش عايزاه نهائي لأن الموضوع ده له مخاطر كبيرة بالنسبة لهم\nخلونا نشوف إيه هي المخاطر من وجهة نظر قريش:\n◇أولا:\nلو دعوة الإسلام انتشرت في الجزيرة العربية احتمال كبير جدا إن قريش تفقد مكانتها وتجارتها، \nلأنهم كانوا بيكسبوا كثير جدا من بيع الأصنام، فمين إللي هيشتري أصنام لما الناس تدخل الإسلام\n◇ثانيا:\nكفار مكة عارفين كويس أوي إن المسلمين مش مهاجرين ليثرب عشان يقضوا فترة راح ويغيروا جو\nدول عارفين إن المسلمين أصحاب قضية، عايزين يقيموا دولة إسلامية وهيرجعوا في يوم من الأيام عشان يحكموا مكة،\nما هو رسول الله ﷺ  بقاله ثلاثة عشرة سنة بيقول لهم إن الحكم لله فقط،\nفأكيد المسلمين هيرجعوا في يوم من الأيام عشان يقيموا حكم الله في مكة\n◇ثالثا:\nهجرة المسلمين ليثرب بالذات كان مشكلة بالنسبة لهم لأن يثرب فيها مميزات مش موجودة في أي مكان تاني وده مش في مصلحة قريش نهائي، ومن المميزات دي:\n♡إن سكان يثرب إللي هم الأوس والخزرج من أعز قبائل العرب وأقواهم  في الحرب، \nولولا إنهم كانوا مشغولين في الحرب إللي كانت بينهم كان زمانهم بقوا قوة كبيرة مشهورة في الجزيرة العربية تهدد باقي القبائل\nفتخيلوا القوة دي لما تنضم لرسول الله ﷺ بعد ما يتوحدوا هتبقى عاملة إزاي\n♡موقع يثرب الجغرافي بيهدد قوافل قريش، لأنها تقع على طريق قوافل قريش من وإلى الشام،\nفيثرب تقدر تعمل حصار على مكة وتجارتها في أي وقت، وده هيسبب لهم خسارة كبيرة جدا لأن عيشتهم كلها على التجارة \nده غير إن يثرب مدينة حصينة، يعني محمية حماية طبيعية محدش يقدر يهجم عليها بسهولة\nفحتى لو فكروا إنهم يحاربوا أهل يثرب فهتكون حرب صعبة جدا عليهم\n♡يثرب بيسكنها اليهود، وهم أهل سلاح وأموال وأعداد كبيرة، وهم أهل كتاب وأتباع الانبياء، وكانوا عارفين إن ده زمن خروج آخر الأنبياء،\n والمتوقع إنهم هيدخلوا في الإسلام ويتبعوا رسول الله ﷺ،\nوده مصيبة كبيرة جدا لأهل مكة\nبالإضافة لكل إللي فات ده، الناس إللي هاجرت دي من أهل مكة أصلا، يعني كل واحد من زعماء مكة إما فقد ابن أو أخ أو ابنة، وفي ناحيتهم حب فطري،\nولولا محمد ﷺ  والدين إللي جاء به ده مكنش كل ده حصل،\nفهم في ضغط نفسي رهيب ومتغاظين جدا من الحال إللي وصلت له الأمور ومحتاجين يشوفوا حل\nوالحل الأساسي إنهم ميسمحوش لمحمد ﷺ إنه يهاجر ليثرب، لأن محدش من المسلمين ولا الأوس والخزرج هيقدر يعمل أي حاجة إلا لما يكون محمد ﷺ بينهم،\nيبقى لازم يسيطروا على محمد ﷺ ويمنعوه من الهجرة بأي طريقة\nلكن إزاي هيسيطروا عليه وهو من قبيلة بني هاشم القوية، وصعب إنهم يدخلوا معاها في صراع\nعشان كده اجتمعوا في دار الندوة ، ودي زي قاعة اجتماعات كده، محدش بياخد قرارات مهمة إلا في دار الندوة دي،\nفكل رؤوس المشركين من قريش من القبائل المختلفة ماعدا بني هاشم طبعا، اجتمعت في دار الندوة عشان يشوفوا حل للأزمة بتاعتهم دي\n☆وبمناسبة اجتماع المشركين، قصة إن إبليس تمثل في صورة شيخ من نجد وحضر معاهم اجتماع دار الندوة غير صحيحة\nأصلا بالعقل محدش بيدخل دار الندوة دي وبيحضر اجتماعاتها غير سادة قريش، فإزاي هيدخلوا رجل غريب وسطهم في اجتماع مهم زي ده\nالمهم هم اجتمعوا وبدأ كل واحد فيهم يقول الحل إللي عنده للمشكلة دي، كان عندنا فريقين: \nفريق معتدل كان شايف إن حبس رسول الله ﷺ في مكة كفاية عشان يحل المشكلة\nالفريق التاني كان زي ما بنقول عليه دلوقتي وبنسميه اليمين المتطرف\nده كان رأيه إن رسول الله ﷺ لازم يُقتل عشان المشكلة تتحل من جذورها،\nوالفكرة دي كانت عاجبة الجميع لكن مين إللي هيضحي بنفسه ويواجه قبيلة بني هاشم\nماهو أي قبيلة قوية يُقتل حد من أشرافها مش بيسبوا دمه يروح هدر \nفراح أبو جهل طالع لهم بفكرة شيطانية قال لهم:\nاحنا هنختار من كل قبيلة شاب قوي ونخليهم يحاصروا بيت محمد، وأول ما يطلع من بيته يقوموا كلهم ضاربينه بالسيوف ضربة رجل واحد وبكده دمه يتفرق بين القبائل،\nوبني هاشم مش هيبقى قصادهم حل غير إنهم يقبلوا بالدِّيَة، لأنهم مش هيقدروا يحاربوا كل قبائل العرب\nفعجبهم رأي أبو جهل جدا واتفقوا على كده فعلا،\nلكن....ويمكرون ويمكر الله\nربنا أخبر رسول الله ﷺ عن طريق جبريل عليه السلام قال الله عز وجل:\n\"وَإِذْ يَمْكُرُ بِكَ الَّذِينَ كَفَرُوا لِيُثْبِتُوكَ أَوْ يَقْتُلُوكَ أَوْ يُخْرِجُوكَ وَيَمْكُرُونَ وَيَمْكُرُ اللَّهُ وَاللَّهُ خَيْرُ الْمَاكِرِينَ \"\nوأمره جبريل عليه السلام بالهجرة ليثرب،\nفهنسيب كفار مكة يخططوا ويجمعوا الشباب ونخلينا مع رسول الله ﷺ  عشان نشوفه هيتصرف وهيعالج المشكلة دي إزاي\nرسول الله ﷺ عنده كذا مشكلة محتاجة حل \nأولها هل أبو بكر الصديق جاهز للسفر في الميعاد إللي جبريل عليه السلام حدده له،\nلأن أبو بكر هسيب أهله كلهم...أمه وأبوه وزوجته وبناته ويمشي مع رسول الله ﷺ،\nورسول الله ﷺ عنده أمانات الناس محتاجة ترجع،\nهم أه كانوا بيكذبوه وبيؤذوه، لكن مفيش مانع يأتمنوه على أموالهم\nفإزاي هيلحق يرجعهم وهو لازم يطلع قبل الفجر قبل ما قريش تجتمع على قتله\nأول حاجة حب يرتب مع أبو بكر رضي الله عنه هيطلعوا إمتى ويمشوا إزاي،\nولأن الموضوع محتاج سرية تامة رسول الله ﷺ راح لأبو بكر في وقت الظهر، يعني الوقت ده مجدش بيطلع فيه من بيته بسبب الحر، \nوكمان زيادة في السرية كان مغطي رأسه ووجهه بملابس، كأنه لابس قناع يعني\nأول ما وصل لبيت أبي بكر الصديق ودخل ، كل إللي في البيت استغرب من مجيء رسول الله ﷺ في الوقت ده لأنه مش من عادته إنه يزورهم في الوقت ده \nفقالوا أكيد في حاجة \nفقال رسول الله ﷺ لأبي بكر أخرج الناس إللي عندك، يعني عايز يكون مع أبو بكر لوحده،\nفقال له أبو بكر: \nمفيش حد غريب، دول أهلك يا رسول الله،\nوكان إللي موجودين هم أسماء وعائشة ابنتا أبي بكر، وكانت السيدة عائشة في الوقت ده زوجة رسول الله ﷺ، \nفقال رسول الله ﷺ لأبي بكر إن ربنا أذن له بالهجرة،\nفقال له أبو بكر : الصحبة يا رسول الله \nيعني أنا هكون صاحبك في الرحلة دي،\nفرسول الله ﷺ قال له : أيوة إنت هتكون صاحبي في الرحلة دي\nفبكى أبو بكر الصديق رضي الله عنه من الفرحة \nشرف مخصوص لأبي بكر الصديق رضي الله عنه\nحتى السيدة عائشة قالت أنا عمري ما تخيلت إن في حد ممكن يبكي من الفرح لحد ما شفت أبي بكر\nمع إن الموضوع خطير ولو المشركين مسكوهم هيقتلوهم لكنه متصورش للحظة إنه ممكن يفارق رسول الله ﷺ، \nوعشان كده كان مجهز راحلتين عشان كان عنده أمل إنه يهاجر مع رسول الله ﷺ، \nلأنه لما كان ناوي يسافر ليثرب رسول الله ﷺ قال له متسافرش دلوقتي يمكن ربنا يجعل لك صاحب يسافر معاك،\nفأبو بكر قعد يجهز في الراحلتين دول لحد ما ييجي الوقت إللي هيقدر يسافر فيه\nفقبل ما رسول الله ﷺ يسأل أبو بكر هنسافر إزاي كان أبو بكر قايله يا رسول الله في راحلتين أنا مجهزهم\n☆وموقف أبو بكر الصديق يعلمنا حاجة مهمة ، وهي إننا نكون مستعدين دايما للأمور المهمة إللي منعرفش هتحصل إمتى وأهم الحاجات دي ...الموت...احنا ممكن نموت في أي وقت، والموت هو تقريبا الحاجة الوحيدة إللي بيشترك فيها كل البشر،\nفهيحصل هيحصل...عشان كده لازم نكون مستعدين\nبدأ رسول الله ﷺ يرتب مع أبو بكر الصديق رضي الله عنه الرحلة هتكون إزاي، \nاحنا اتعودنا من رسول الله ﷺ إن كل حاجة في حياته بيخطط لها وبيرتب لها مضبوط، وبياخد بالأسباب عشان خططه تنجح\nالخطة هتكون كالتالي:\n◇الأمانات إللي عند رسول الله ﷺ هيسيبها لعلي بن أبي طالب وهو يؤديها عنه.\n◇نقطة الإنطلاق هتكون من بيت أبي بكر لأن الراحلتين عنده، وكمان عشان يتجنب حصار قريش إللي هيفرضوه على رسول الله ﷺ لما يتجمعوا عشان يحاولوا يقتلوه.\n◇هيخرجوا من فتحة خلفية من بيت أبو بكر عشان لو كان في أحد من المشركين مراقب باب بيت أبو بكر.\n◇لما يخرجوا مش هيتجهوا لطريق يثرب على طول، لأن ده أول مكان كفار قريش هيدوروا عليه فيه لما يلاقوه اختفى من مكة،\nوهيتجهوا ناحية غار ثور ويقعدوا فيه ثلاثة أيام لحد ما الأوضاع تهدأ شوية في مكة\nوبعدين يتجهوا ناحية يثرب، وفي طريقين ليثرب، طريق سهل ومعروف وطريق تاني مش معروف وطويل وصعب لكنه أكثر أمنا من الطريق المعتاد،\nفهيختاروا الطريق الصعب ده يمشوا فيه عشان هو أكثر أمان\nلكن كده هيواجه رسول الله ﷺ مشكلتين، الأولى : \nإزاي هيقدر يمشي في الطريق الصعب ده وهو ميعرفوش، \nوالمشكلة الثانية : \nخلال الثلاث أيام دي هيسيبوا الجمال بتاعتهم فين ،أي حد هيشوفهم هيشك على طول وهييجوا يدورا\nفكان الحل إنهم يستعينوا بواحد خبير في طرق الصحراء ، وفي نفس الوقت هيسيبوا معاه الجمال بتاعتهم لحد ما ييجي وقت الخروج من الغار بعد ثلاثة أيام،\nلقوا واحد اسمه عبد الله بن أُرَيْقِط مع إنه كان مشرك ولكنه كان ماهر جدا وخبير في طُرق الصحراء\nورسول الله ﷺ اختاره مع إنه مشرك كان لسببين :\nالأول : إنه كان ثقة يعني مش هيروح يشيع سر رسول الله ﷺ، \nوالثاني : إن مكنش في المسلمين حد في خبرته ولا مهارته\nطيب إزاي رسول الله ﷺ وأبو بكر الصديق هيعرفوا إللي بيحصل في مكة وهم في الغار\nيبقى محتاجين حد يجيب لنا الأخبار، فدي هتكون مهمة عبد الله بن أبي بكر الصديق، \nوعشان محدش يتتبع أثار أقدام عبد الله فهنحتاج لعامر بن فُهيرة مولى أبي بكر إنه يأخذ أغنام أبي بكر يمشي بها كأنه خارج لرعيها،\n فيمشي بها على أثار أقدام عبد الله بن أبي بكر،\nشوفوا رسول الله ﷺ بيحسب حساب كل خطوة \nمع إن ربنا كان ممكن ينصره بدون أي تخطيط ولا حاجة ولكن عشان احنا نتعلم الأخذ بالأسباب والتخطيط الصحيح\nاتفق رسول الله ﷺ مع أبي بكر الصديق على الخطة وبعدين رجع لبيته،\n《وفي رواية بتقول إنه خرج على طول مع أبي بكر مباشرة للهجرة ومرجعش بيته، ومقابلش المشركين أصلا》\nبدأ رسول الله ﷺ يجهز نفسه ولما جاء وقت الخروج لقى المشركين محاصرين بيته ومستنيينه يخرج عشان يقتلوه\nفجاء جبريل عليه السلام لرسول الله ﷺ وقال له اخرج من بين المشركين وإنت بتقول :\n\"يس* وَالْقُرْآنِ الْحَكِيمِ* إِنَّكَ لَمِنَ الْمُرْسَلِينَ * عَلَى صِرَاطٍ مُسْتَقِيمٍ * تَنْزِيلَ الْعَزِيزِ الرَّحِيمِ * لِتُنْذِرَ قَوْمًا مَا أُنْذِرَ آبَاؤُهُمْ فَهُمْ غَافِلُونَ *\n لَقَدْ حَقَّ الْقَوْلُ عَلَى أَكْثَرِهِمْ فَهُمْ لَا يُؤْمِنُونَ * إِنَّا جَعَلْنَا فِي أَعْنَاقِهِمْ أَغْلَالًا فَهِيَ إِلَى الْأَذْقَانِ فَهُمْ مُقْمَحُونَ *\n وَجَعَلْنَا مِنْ بَيْنِ أَيْدِيهِمْ سَدًّا وَمِنْ خَلْفِهِمْ سَدًّا فَأَغْشَيْنَاهُمْ فَهُمْ لَا يُبْصِرُونَ\"\nفربنا مش هيخليهم يشوفوك، سواء عن طريق إنه يعمي أبصارهم عنك، أو يخليهم يناموا وهم واقفين،\nخرج رسول الله ﷺ  من وسط المشركين وهو بيقول الآيات وفعلا محدش من المشركين رآه، ووصل لبيت أبي بكر وبدأوا يستعدوا للخروج،\nفجهزت لهم أسماء بنت أبي بكر الماء والطعام إللي هيحتاجوه معاهم في رحلتهم،\nومكنش في أي حاجة تضع لهم فيها الأكل فشقت نطاقها نصفين والنطاق عبارة عن قماشة بتتشد حول الوسط والمرأة بترفع ثوبها عشان ميضيقهاش وهي بتشتغل ويوقعها، \nفشقته ووضعت فيه الأكل والماء وأعطتهم لرسول الله وأبي بكر وكانت حامل في شهورها الأخيرة،\nفسميت في اليوم ده ذات النطاقين\n☆عندنا ثلاث نقط في الجزئية دي \nالنقطة الأولى وهي :\n◇ طلب رسول الله ﷺ من علي بن أبي طالب إنه ينام في فراشه تمويه يعني،\nالقصة دي اختلف فيها أهل العلم هل هي صحيحة ولا لأ،\nفي علماء قالوا إن سندها حسن مقبول، مش صحيحة أوي يعني\nوعلماء قالوا إنها غير صحيحة وسندها فيه ضعف وخصوصا إنها غير منطقية،\nيعني ربنا أصلا أعمى أبصار المشركين عن رسول الله ﷺ يبقى إيه الفايدة من وجود علي بن أبي طالب في فراش رسول الله ﷺ\nّماهو كان ممكن يحط مكانه أي حاجة ويغطيها بدل علي رضي الله عنه\nوخصوصا إن ده هيعرض حياة علي رضي الله عنه للخطر بدون داعي ورسول الله ﷺ من إللي شفناه منه وإزاي هو بياخد احتياطاته في كل حاجة ، \nمش هيعرض حياة علي بن أبي طالب للخطر كده وهو أصلا عنده مهمة تانية وهي تأدية الأمانات إللي عنده\nأنا شخصيا بميل للرأي الثاني إنها ضعيفة لا تصح، بس أنا قلت لكم الرأيين من باب الأمانة يعني\n◇النقطة الثانية هي:\nإن قصة وضع رسول الله ﷺ للتراب على رؤوس المشركين بعد ما خرج من البيت وقرأ أول آيات من سورة يس غير صحيحة \nالمصدر : \n《كتاب : ما شاع ولم يثبت في السيرة النبوية》\n◇النقطة الثالثة هي:\nموضوع إن أسماء بنت أبي بكر الصديق كانت بتروح لرسول الله ﷺ وأبي بكر الصديق في الغار عشان تعطيهم الأكل والماء دي لا تصح مطلقا بأي حال من الأحوال\nالحديث في صحيح البخاري إنها شقت نطاقها وحطت فيه الأكل والماء قبل ما يخرجوا أصلا،\nده غير كده بالعقل يعني هل في رجل يقبل إن امرأة حامل تخرج لوحدها وتمشي ثمانية كيلو رايح جاي عشان تجيب له أكل\nتخيلوا إننا بنتكلم عن رسول الله ﷺ صاحب الأخلاق العظيمة وصاحب المروءة\nده غير إنه كان بيروح يقعد شهر في غار حراء ومعاه الزاد بتاعه فمش هيعرف ياخد زاد لثلاثة أيام\nبلاش دي \nبالعقل يعني عبد الله بن أبي بكر إللي كان بيروح يقول لهم أخبار قريش مكنش عارف يحط في جيبه شوية تمر ويعطيهم لرسول الله ﷺ وأبي بكر\nطيب خدوا دي كمان \nعامر بن فهيرة قال إنه كان بيعطيهم من حليب الغنم إللي كان بيطلع يرعى به عشان يغطي على أثار الأقدام،\nفإيه لازمة أسماء رضي الله عنها إنها تروح تعطيهم الأكل\nللأسف الروايات الباطلة دي بتظهر رسول الله ﷺ والإسلام في صورة سيئة أكثر ما تظهر إن المرأة لها دور وكلام كتير كده \nأنا شخصيا وأنا صغيرة كنت أقول إزاي رسول الله يرضى إن امرأة حامل وتعبانة كده تروح تجيب لهم الأكل إيه لازمة الرجالة يعني\nفالحمد لله إنها طلعت رواية باطلة \nدين الإسلام يوافق الفطرة، فلما تلاقوا نفسكم سمعتم حاجة وإنتم مش مستريحين لها دوروا هل هي فعلا حاجة صحيحة في الدين ولا لأ\n \nخليكم فاكرين حديث رسول الله ﷺ:\n\"اسْتَفْتِ قَلْبَكَ وَاسْتَفْتِ نَفْسَكَ ثَلَاثَ مَرَّاتٍ الْبِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ \"\nجهز رسول الله ﷺ نفسه مع أبي بكر الصديق وخرجوا وبدأو رحلتهم ،\nهل هتنجح خطة رسول الله ﷺ في تضليل المشركين ولا إيه إللي هيحصل ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 73, "l": "الجزء 47 | في طريق الهجره", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_السابعة_والأربعون\n#في_طريق_الهجرة\nكنا واقفين عند رسول الله ﷺ لما تجهز هو وأبو بكر رضي الله عنه عشان يهاجروا من مكة ويتجهوا ليثرب وشرحنا الخطة بتاعتهم،\nلما خرج رسول الله ﷺ من مكة نظر إليها وقال :\n\"وَاللهِ إِنَّكِ لَخَيْرُ أَرْضِ اللهِ وَأَحَبُّ أَرْضِ اللهِ إِلَيَّ، وَاللهِ لَوْلَا أَنِّي أُخْرِجْتُ مِنْكِ مَا خَرَجْتُ\"\n☆محتاجين نقف هنا وقفة عشان نفهم معنى مهم جدا\nحب الوطن ده من المشاعر الفطرية في الإنسان،\nزي حب الإنسان لأولاده وأمه وأبيه وحبه لكل شيء جميل وطبيعي إن الإنسان يحب يقضي حياته في المكان إللي له فيه ذكريات جميلة،\nحلو الكلام\nطيب لو الإنسان اتمنع إنه يُظهر دينه زي مثلا إنه مش عارف يؤدي الصلاة وباقي شعائر الإسلام والناس بتحاربه وبتؤذيه يبقى هنا الوضع إيه\nيبقى يعمل زي رسول الله ﷺ ويسيب وطنه ده ويروح مكان تاني يقدر يُقيم فيه دينه ويعبد ربنا براحته، \nطبعا لو كان يقدر إنه يسيب وطنه ده\nوالهجرة دي واجبة على الإنسان لو يقدر ، قال تعالى:\n \"يَا عِبَادِيَ الَّذِينَ آمَنُوا إِنَّ أَرْضِي وَاسِعَةٌ فَإِيَّايَ فاعبدون\"\nوإللي ميقدرش يهاجر يخفي إيمانه لحد ما ربنا يسهل له أمره،\nزي المسلمين إللي معرفوش يهاجروا من مكة واتحبسوا فيها،\nفاحنا عندنا في الإسلام الحفاظ على الدين مقدم على كل شيء\nوبالمناسبة الحديث المشهور بتاع : \n\"حب الأوطان من الإيمان\" \nحديث موضوع\nوحتى بالعقل يعني حب الأوطان بيشترك الناسِ فيه من غير فرق بين أهل التقوى والإيمان وأهل الكفر والفسوق والعصيان،\nيبقى فين الإيمان بقى\nوحتى رسول الله ﷺ لما قال كلامه ده مكنش يقصد حب الأرض ذات نفسها ولا التراب مثلا ولا لأنها وطن وهيفارقه بقى وكده \nلكن لأن مكة خير بقاع الأرض عند الله تعالى بنص الحديث \nفي رواية تانية: \"وَأَحَبُّ أَرْضِ اللهِ إِلَى الله\"\nوده لأنها أماكن عبادة وفيها الحج وفيها تعظيم شعائر الله،  وربنا قال: \n\"وَمَن يُعَظِّمۡ شَعَٰٓئِرَ ٱللَّهِ فَإِنَّهَا مِن تَقۡوَى ٱلۡقُلُوبِ \"\n ورسول الله ﷺ يقول: \"أَحَبُّ البِلَادِ إِلَى اللهِ مَسَاجِدُهَا\"\nفالخلاصة إن حب الوطن حب فطري لكن لو تعارض مع إقامة الدين يبقى يجب علينا لو نقدر نسيب الوطن ونروح مكان تاني نقيم فيه ديننا\nطيب وإللي مش هيعمل كده ، يعني إللي مش عارف يقيم دينه ومع ذلك مش هيهاجر مع إنه يقدر ده إيه نظامه\nللأسف آخرته وحشة\nشوفوا ربنا بيقول إيه :\n\"إِنَّ الَّذِينَ تَوَفَّاهُمُ الْمَلَائِكَةُ ظَالِمِي أَنفُسِهِمْ قَالُوا فِيمَ كُنتُمْ ۖ قَالُوا كُنَّا مُسْتَضْعَفِينَ فِي الْأَرْضِ ۚ \nقَالُوا أَلَمْ تَكُنْ أَرْضُ اللَّهِ وَاسِعَةً فَتُهَاجِرُوا فِيهَا ۚ فَأُولَٰئِكَ مَأْوَاهُمْ جَهَنَّمُ ۖ وَسَاءَتْ مَصِيرًا\"\nفرسول الله ﷺ ترك وطنه لأنه مش قادر يُقيم فيه دينه وخرج هو وأصحابه من المسلمين لأرض ثانية عشان يعبدوا الله فيها،\nاتجه رسول الله ﷺ مع أبي بكر الصديق رضي الله عنه لحد ما وصلوا لغار ثور وده كان في أواخر صفر من السنة الرابعة عشة للبعثة ،\nوبدأ تنفيذ الخطة من جميع الأطراف كل واحد عارف دوره،\nفي الوقت إللي كان فيه رسول الله ﷺ في الغار مع أبي بكر الصديق،  كانت مكة مقلوبة\nمحمد ﷺ اختفى، راح فين.. طلع من مكة إزاي ...طيب فين أبو بكر.. مش لاقيينه هو كمان ...كده كل إللي كانوا خايفين منه هيحصل\n☆وهنا في قصة مشهورة لكنها غير صحيحة\nبعد ما خرج رسول الله ﷺ ومعاه أبو بكر للهجرة جاء مجموعة من كفار قريش وعلى رأسهم أبي جهل وسأل عن أبي بكر فأسماء قالت إنها متعرفش فراح أبو جهل ضربها ضربة وقعت الحلق من أذنها،\nالقصة دي مع شهرتها لكنها غير صحيحة\nدي آخر فرصة ممكن يلحقوا فيها رسول الله ﷺ  قبل ما يهاجر، فطلعوا على الطرق يدوروا عليه،\nحطوا مكافأة مائة ناقة لأي حد يلاقيه أو يقتله، ومائة ناقة في زمانهم كانت مبلغ كبير\nفكل الناس بدأت تدور عشان تاخد المكافأة، كل مجموعة أخذت مكان تبحث فيه، وصل مجموعة من المشركين عند غار ثور إللي فيه رسول الله ﷺ  وأبو بكر،\nوقف المشركون على باب الغار وقعدوا يتكلموا، ولو واحد منهم بص لتحت رجله كده هيشوفهم\nمتخيلين موقف رسول الله ﷺ وأبو بكر بعد الخطة المحكمة دي، لقوا المشركين واقفين في المكان إللي هم فيه،\nولو المشركون شافوا رسول الله ﷺ وأبو بكر المرة دي  هيقتلوهم أكيد\nفكان أبو بكر الصديق رضي الله عنه خايف وقال لرسول الله ﷺ: \nيا رسول الله لو واحد منهم بص تحت رجله هيشوفنا\nفقال له رسول الله ﷺ : \nمتخفش! تخيل لما يكون اثنين الله ثالثهما إيه إللي ممكن يحصل، ربنا معانا\n\" إِذْ يَقُولُ لِصَاحِبِهِ لَا تَحْزَنْ إِنَّ اللَّهَ مَعَنَا ۖ \"\nفهنا ربنا أنزل عليهم السكينة وساعدهم بجند من جنوده،\nوهي الملائكة، فهي صرفت بصر المشركين عن النظر لداخل الغار،\n\"فَأَنزَلَ اللَّهُ سَكِينَتَهُ عَلَيْهِ وَأَيَّدَهُ بِجُنُودٍ لَّمْ تَرَوْهَا.\"\nومشي المشركون وتركوا الغار من غير حتى ما يفكروا ينظروا داخل الغار بعد ما قطعوا المشوار الطويل ده كله في طريق صعب وفي الحر\nودي حاجة عجيبة يبان فيها فعلا معجزة حقيقية، يعني أنا بدور على حاجة وأول ما أوصل لمكان احتمال كبير ألاقي فيه إللي بدور عليه لا أنظر فيه وأسيبه وامشي\nفكان إللي صرفهم هو الله سبحانه وتعالى، عشان يقول لرسول الله ﷺ ويقول لنا احنا كمان إن مهما خططتم ومهما دبرتم ومهما أخذتم بالأسباب فأنا إللي بإيدي كل شيء،\nوالتوفيق من عندي أنا،\nورسول الله ﷺ بيعلمنا إننا في أشد المواقف لازم يكون عندنا يقين تام بالله، وإن محدش في الكون ده كله يقدر يعمل حاجة إلا بإذن الله\nفطبيعي إن رسول الله ﷺ يكون هادئ، لأنه عارف كويس إن ربنا لن يخذله\n☆وطبعا هنا مننساش نقول إن قصة العنكبوت والحمامتين إللي كانوا معششين على باب الغار وإن في شجرة نبتت على باب الغار، كل دي قصص غير صحيحة\nوأصلا الإعجاز في إن ميكونش في حاجة على باب الغار عشان تبان قدرة ربنا الظاهرة ،\nده غير إن القصص دي مخالفة لكلام ربنا في القرآن\n\"وَأَيَّدَهُ بِجُنُودٍ لَّمْ تَرَوْهَا\"\nيعني التأييد هنا كان من الملائكة الغير ظاهرة، بعكس نسج العنكبوت والحمامة إللي هم جنود رآها المشركون\nقعد رسول الله ﷺ في الغار مع أبي بكر الصديق رضي الله عنه ثلاثة أيام زي ما كانوا مخططين،\nخلال الأيام الثلاثة دي كان بدأ البحث عن رسول الله ﷺ يهدأ شوية شوية، \nوبعد الثلاثة أيام مانتهوا جاء عبد الله بن أُريقط ومعاه الناقتين عشان رسول الله ﷺ يبدأ رحلته إلى يثرب،\nبدأوا يمشوا من الطريق الصعب فلفت نظر رسول الله ﷺ حركة أبو بكر الصديق الغريبة،\nشوية يمشي قصاده، وشوية يمشي وراه ، فرسول الله ﷺ سأله: مالك يا أبا بكر، ليه بتمشي كده؟\nفقال له أبو بكر الصديق رضي الله عنه بكل حب:\nيا رسول الله! \nافتكر الناس إللي بيطاردونا فأمشي خلفك،\nوبعدين أخاف لحد يكون حاطط لنا كمين فأمشي قصادك\nيعني أبو بكر الصديق بيقول لرسول الله ﷺ بطريقة عملية:\n أنا مش مهم.. إنت أهم مني.. أنا أفديك بروحي يا رسول الله\nوهم ماشيين كده شافهم من بعيد بعض المشركين لكنهم مكنوش متأكدين، فلما رجعوا مكة قابلوا واحد اسمه سراقة بن مالك، فقال له واحد منهم:\n احنا شفنا ناس ماشيين على طريق الساحل، ممكن يكون محمد وصاحبه\nفسراقة عايز يأخذ المكافأة لوحده\nفراح قايل لهم: \nلالا مش هم خالص ..ده فلان وفلان لسه كانوا طالعين من عندنا من شوية\nوبعد ما مشيوا من عنده، راح يستعد عشان يخرج وراء رسول الله ﷺ،\nدخل خيمته واستقسم بالأزلام، يعني شاف حظه بيقول له أه اطلع المشوار ده ولا لأ، وده من الشرك إللي ربنا نهى عنه\nفطلع له على الخشبة: لا\nلكن هو عايز يطلع دي مائة ناقة\nفعادي كأنه مشفش حاجة وراح لبس الدرع بتاعه وأخذ سلاحه وفرسه وطلع ناحية رسول الله ﷺ.\n☆ أهه موقف سراقة ده عامل زي مثلا لما واحدة فينا بتستخير ربنا في شيء هي عايزاه وحاباه وتلاقي نتيجة الاستخارة إن ربنا بيعقد لها الأمور،\nيعني بيقول لها ابعدي ده مفيهوش خير، بس عشان هي هواها في الموضوع وعايزاه تلاقيها خالفت نتيجة الاستخارة ومكملة،\nوبعدين لما تحصل الكارثة تقول ياريتني مكنت كملت\nفضل سراقة ماشي بفرسه لحد ما أبو بكر رضي الله عنه شافه جاي من بعيد فأبو بكر خاف وقال :\nيا رسول الله ..دول لحقونا\nفرسول الله ﷺ قال له : كلا...ودعا رسول الله ﷺ على سراقة فقال :اللهم اكفيناه بما شئت\nففي نفس اللحظة رجل الفرس غاصت في الأرض ووقعت على وجهها وغاصت لحد ما بقت بطنها لازقة في الأرض \nفنط سراقة من عليها وهو بيقول إيه ده\nفبدأ يقوم الفرس فقامت وهي بتحمحم يعني بتعمل صوت إللي هو صوت الفرس،\nوأول ما قامت لقى دخان من غير ما يكون في نار، فعرف ساعتها سراقة إن رسول الله ﷺ ممنوع منه،\nيعني لا يمكن الوصول إليه ولا القبض عليه ولا إيذائه\nفمبقاش عارف يعمل إيه\nفنادى على رسول الله ﷺ وطلب منه إنه يعطي له الأمان،\nسبحان الله \nإللي معاه السلاح والعتاد هو إللي بيطلب الأمان \nفقال سراقة لرسول الله ﷺ:\nأنا عرفت إن إللي حصلي ده بسببك، فادعي ربنا إنه ينجيني وأنا والله ما هقول لأحد عليك وهبعد عن طريقك أي حد يطلع يطاردك\nوكمان على الطريق هتلاقوا الإبل بتاعتي، فقولوا للراعي يعطيكم من اللبن بتاعها وخذوا سهم من السهام بتاعتي عشان تبقى علامة لكم عند الراعي،\nفرفض رسول الله ﷺ إنه يأخذ منه شيء،\nفي اللحظة إللي فرس سراقة غاصت في الأرض عرف إن رسول الله ﷺ هيظهر وينتصر على الناس في يوم من الأيام فأحب إنه ياخد من رسول الله ﷺ الأمان يعني عايز رسول الله ﷺ يكتب له كتاب يعطي له فيه الأمان عشان لو حصل حاجة في المستقبل،\nفأمر رسول الله ﷺ عامر بن فهيرة إنه يكتب له كتاب يعطي له فيه الأمان، وفي رواية تانية طلب من أبي بكر الصديق،\nوفعلا سراقة هيستخدم كتاب الأمان ده بعدين\nفقال سراقة لرسول الله ﷺ : أؤمرني يا نبي الله وأنا هعمل إللي إنت عايزه\nبيقول له نبي الله وهو مشرك متخيلين التحول إللي حصل\nفقال له رسول الله ﷺ: متخليش حد ييجي ورانا\nفرجع سراقة وأول ميشوف حد رايح في اتجاه طريق رسول الله ﷺ  يقول له: \nخلاص محدش يروح الطريق ده أنا فتشت فيه، روحوا دوروا في مكان تاني\n☆ وبما إننا بنتكلم عن سراقة فقصة إن رسول الله ﷺ وعد سراقة بسواري كسرى قصة ضعيفة لا تصح عن رسول الله ﷺ هي كمان\nالواحد عمال ياخد صدمات عجب\nاستمر رسول الله ﷺ في رحلته، فوهو ماشي قابل في الصحراء دي بدون أي ميعاد سابق ابن عمته الزبير بن العوام كان راجع من الشام في قافلة مع بعض المسلمين،\nوكان مع الزبير ملابس جاي بها من الشام فأعطى ثوبان أبيضان لرسول الله ﷺ وأبو بكر الصديق رضي الله عنه،\nواستكمل رسول الله ﷺ رحلته،\nلحد ما وصلوا خيمة لامرأة في الصحراء وكان لها مع رسول الله ﷺ قصة\nقصتها إيه مع رسول الله ﷺ \nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 74, "l": "الجزء 48 | وصف رسول الله ووصوله للمدينه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثامنة_والأربعون\n#وصف_النبي_المصطفى\n#وصول_رسول_الله_للمدينة\nاتكلمنا المرة إللي فاتت عن رسول الله ﷺ لما خرج من مكة وقعد في غار حراء ثلاثة أيام وبعدين بدأ رحلته ليثرب،\nوشفنا إللي حصل مع سُراقة بن مالك ومقابلة رسول الله ﷺ  للزبير بن العوام في الطريق،\n☆قبل ما نكمل الأحداث في قصة مشهورة عن أبي بكر الصديق في الهجرة لكنها غير صحيحة،\nمقلتهاش في الجزء إللي فات لحد ما اتأكد،\nوفعلا طلعت قصة غير صحيحة ملهاش سند صحيح بيذكرها أهل السيّر وهي إن قبل ما رسول الله ﷺ يدخل غار ثور دخل أبو بكر الصديق وبدأ يقفل الثقوب في الغار ما عدا واحد أغلقه برجله،\nفلدغه عقرب أو ثعبان ورسول الله ﷺ  كان نايم على حجره فبكى أبو بكر من الألم فنزلت الدموع على خد رسول الله ﷺ...إلى آخر القصة،\nفالقصة دي غير صحيحة، هتلاقوا تفصيل الموضوع في موقع الفتاوى إسلام ويب \nنرجع لرسول الله ﷺ ونشوف معاه إللي هيحصل، لما كان ماشي في القافلة الصغيرة بتاعته مرّوا على خيمة لامرأة بدوية كبيرة في السن قوية و عاقلة غير مشهورة في الجاهلية اسمها أُم مَبعد الخُزَاعية،\nوكانت قصاد الخيمة بتعمل أشغالها لما مر عليها رسول الله ﷺ، \nفسألها لو عندهم تمر أو لحم يشترونه، فملقاش عندها حاجة وكانت فقيرة، وكان أصابهم قحط فقالت له:\nوالله لو عندنا حاجة كنت هضيفكم من غير ما تطلبوا\nفرأى رسول الله ﷺ في الجنب كده شاة هزيلة ضعيفة ، فسأل أم معبد هي إيه دي؟\nفقالت له أم معبد : دي شاة مخرجتش مع باقي الأغنام في الرعي لأنها هزيلة ومُجهدة مش هتقدر تتحرك\nفقال لها رسول الله ﷺ: \nطيب تأذني لي إني أَحلِبها؟\nفقالت له : أه عادي.. لو كان فيها لبن \nفجاب الشاة ومسح على ضرعها وقال:\n بسم الله، اللهم بارك لها في شاتها، \nفاتملى ضرع الشاة باللبن وطلب إناء طبق كبير، فحلب فيه لبن كثير وبعدين أعطاها اللبن تشرب لحد ما شبعت،\nوسقى أبا بكر وشرب هو في الآخر ﷺ،  وبعدين ملأ لها الإناء وتركه عندها ومشي.\nأنا متخيل شكل أم معبد وهي مستغربة ومتفاجئة من إللي شافته\nمعجزة ظاهرة واضحة قصادها\nبعد شوية إلا وزوجها أبو معبد قادم ومعاه أغنام هزيلة بيتمايلوا من شدة الضعف، مش قادرين يمشوا،\nفلما شاف اللبن قال لها : \nانتِ جبتي اللبن ده منين والشاة إللي عندك هزيلة ضعيفة عزباء ومفيش ولا شاة تانية في البيت فيها لبن\nقالت : أيوة صح معاك حق، لكن احنا عدّى علينا رجل مُبارك\nوقعدت تحكي لأبي معبد القصة إللي حصلت معاها، فقال لها: طيب إوصفيه لي كده\nفقالت له بتوصفه بالإضافة لوصف الصحابة:\nأنا شفت رجل ظاهر الجمال والحسن، رأسه ضخمة مش رأس صغيرة يعني ،والرأس الكبيرة في الرجال من مظاهر الحُسن عند العرب\nشعره أسود ولا هو شعر مجعّد ولا الشعر الناعم أوي المسترسل ده ، لأ.. شعره مفرود وحلو،\n☆وكان رسول الله ﷺ ساعات يقصه عادي، وساعات يتركه لحد ما يوصل لكتفه، فإللي بيطول شعره ويقول أصله سنة ده كلامه خطأ،\nده بيتبع هواه مش أكثر بمناسبة الموضة والكلام ده\nوإلا كان أَوْلى إنه يتبع سنة رسول الله ﷺ في حاجات تانية فيها نص شرعي، زي صلاة السنن وصيام الإثنين والخميس واستخدام السواك وغيرها من السنن المهجورة\nماهو احنا ناخد سنة النبي ﷺ كلها على بعضها مش هنقّي\nأما وجهه فكان مدوّر ولون بشرته مش أبيض أوي زي الدقيق كده ولا هو أسمر ، بياضه كان بياض فيه حُمرة،\nإذا سُر يعني فَرِح، تقاطيع وجهه بتنور كأنه بيلمع زي الذهب،\nوإذا تبسم الدنيا تنوّر، \nوكان بيتعرف السرور ده في وجهه يعني كان على الفطرة، مشاعره إللي في قلبه ظاهرة على وجهه، إذا استحى...إذا كره شيء...إذا أحب شيء....\nحتى لما كان بيغضب كان بيبان على وجهه، مش زي مثلا إللي ممكن يكون بيغلي من جواه فيظهر ابتسامته ويبان كأنه عادي\nومحدش كان أجمل منه، كأن الشمس تجري في جبهته يعني جبهته عريضة وبتلمع ..منورة، عينه واسعة، حرف رموشه يعني المكان إللي بيطلع منه الرموش..منبت الرموش فيه حُمرة،\nورموشه نفسها طويلة وكثيفة، \nحدقة العين شديدة السواد والبياض إللي حولها شديد البياض، تحس إن عينه مكحلة مع إن مفيش فيها كحل، حواجبه طويلة ورفيعة مقوسة ومليانة شعر، \nإللي يشوف حواجبه يحسهم متصلين ببعض لكنهم مش متصلين، \nالجزء إللي بين حواجبه من بداية الأنف أبيض مفيهوش شعر، لكن فيه عِرق لما يغضب بيظهر العرق ده ويبقى بارز،\nوجهه مش مليان شعر، الشعر موجود في محيط اللحية وخدوده ناعمة،\nوكان بيعرق كثير وكان العرق في وجهه عامل زي حبات اللؤلؤ،\nأنفه طويلة وأرنبة أنفه صغيرة ..نهاية أنفه يعني، وفي وسط الأنف حَدب يعني في ارتفاع عند قصبة الأنف بدون ما يكون شكلها قبيح،\nفمه كبير وأسنانه بيضاء في بينها فواصل، يعني متفرقة وكل سِنّة متحددة لوحدها،\nلما يضحك أسنانه بتبرق تحس إنه بيتلألأ، شعر لحيته ضخم وكثيف لونه أسود يصل طول لحيته لحد صدره وشكلها جميل، لما يتكلم في سرّه الناس إللي وراه يعرفوا إنه بيتكلم بسبب تحرك لحيته، فهي كانت باينة لهم،\nمكنش بيقصّر لا من طول اللحية ولا من عرضها، الجزء إللي تحت الشفاة السّفْلى فيه سبعة عشرة شعرة بيضاء،\nأما شاربه فكان بيُحفيه يعني بيقصره جدا لحد ما يتبقى منبت الشعر، لكنه مكنش بيحلقه.\n☆وبما إننا بنتكلم عن لحية رسول الله ﷺ يبقى لازم نوضح حكم شرعي مهم\nلا يجوز للرجل إنه يحلق لحيته، لأن حلق اللحية حرام ،\nفهو: \n◇معصية لأمر رسول الله ﷺ، \n◇ومخالفة لسنته وسنة الأنبياء جميعا ومتبع لسنة المجوس والمشركين، \n◇ومخالفة للفطرة، وفيها تغيير لخلق الله،\n◇وكمان تشبه بالنساء ومجاهرة بالمعصية\nشوفتم كم معصية\nفحالق اللحية آثم ، لأن الأمر بإعفاء اللحية وتركها وعدم حلقها أو التعرض لها ،\nكلها أوامر صريحة في أحاديث صحيحة مفيهاش أي نقاش أو تأويل أو حتى في اختلاف بين العلماء،\nعارفين العلماء مختلفين في إيه في موضوع حلق اللحية\nمختلفين:\nهل حلق اللحية كبيرة من الكبائر ولا حلقها يدخل في صغائر الذنوب..متخيلين..يعني كده كده في ذنب \nحتى العلماء إللي قالوا إن حلق اللحية تدخل في صغائر الذنوب قالوا إنه يتخاف على إللي بيحلقها إن ذنبه يدخل في الكبائر بسبب إصراره على حلقها ومداومته على كده\nوطبعا احنا متعودين مناخدش كلام من أحد إلا بدليل \n¤وقبل ما حد يقول ما الملتحين فيهم وفيهم وفيهم\nماشي ...بس إيه علاقة اللحية بالموضوع يعني\nاللحية مجرد شريعة وأمر زي باقي شرائع الإسلام وأوامره،\nواحد فيه كل العبر بس قدر ينفذ أمر رسول الله ﷺ  بإنه يُطلق لحيته،\n فاحنا نقوله لأ احلق لحيتك عشان إنت فيك العبر، يعني زوّد كمان معصية لمعاصيك \nالمشكلة مش في الملتحين على فكرة المشكلة فينا احنا\nاحنا متصورين إن الملتحين دول ملايكة بقى ومبيغلطوش،\nفلما واحد ملتحي يعمل حاجة نقول أاااه شوف الملتحي\nاحنا اللي ربطنا ما بين اللحية والإلتزام الملائكي،\nكان على عهد رسول الله ﷺ الملتحي إللي زنى ..والملتحي إللي كان بيشرب الخمر،\nهل رسول الله ﷺ كان بيقول لحد فيهم عيب على لحيتك دي ولّا روح احلق لحيتك \nالمطلوب الناس هي إللي تغير مفهومها عن اللحية ويتقبلوها زي ما بيتقبلوا إن الرجل له عين وفم ويد عادي جدا\n☆ثواني بقى عشان متحصلش كارثة\nمفيش واحدة تروح لباباها ولا أخوها ولا زوجها وتقول له إنت آثم عشان بتحلق لحيتك\nده ممكن يحدفك بطوبة أنا مليش دعوة\nالحاجات دي متتاخدش قفش كده، لازم تدعيهم بأسلوب كويس وتفهميهم مين هو رسول الله ﷺ الأول وإننا لازم نتشبه به، \nمرحلة الحكم الشرعي دي بتيجي في الآخر خالص بعد الترغيب ودعوة الناس بالحسنى وخصوصا لو ناس متعرفش حاجة عن الدين\nنرجع لوصف رسول الله ﷺ ونشوف رقبته كانت عاملة إزاي،\nرقبته كانت طويلة وبيضة عاملة زي إبريق الفضة، أكتافه عريضة وصدره واسع وكانت بطنه وصدره حتة واحدة  مكنش عنده كرش يعني\nوقلنا إنه كان بيعرق كثير وكان عرقه ده ريحته زي ريحة المسك،\nوظهره كان عامل زي سبيكة فضة ظهره حتة واحدة، وكان على ظهره خاتم النبوة واحنا شرحنا شكله قبل كده،\nأما ذراعه فكانت طويلة ومليانة شعر،\nوكان كف إيده ضخم وعريض وكانت ناعمة جدا وأَليَن من أي حرير وكانت أبرد من الثلج، وريحتها أحلى من المسك ﷺ \nلما كان بيمشي رجله كلها بتكون على الأرض يعني كلها حتة واحدة،\nوهو مكنش طويل أوي ولا قصير كان طوله متوسط،\nجسمه بصفة عامة كان جامد كده الجسم إللي فيه عضلات متساوية ده وبيبقى حتة واحدة بيقولوا عليه مِدَمْلِك\nولما كان بيمشي كان بيمشي بسرعة ومحدش كان بيمشي أسرع منه،\nولما بيلتفت يلتفت بجسمه كله مش بيلتفت برأسه بس،\nولما بيعتدل بيعتدل بجسمه كله،\nلما كان بيتكلم كلامه بيكون مُفصل، كل كلمة لوحدها والحروف باينة، يعني القاف قاف والكاف كاف، \nبيتكلم باللسان والشفتين كلام واضح لدرجة إن إللي قصاده يقدر يعد الكلمات إللي قالها\nوكان صوته فيه بَحّة خفيفة مش صوت بيسرسع \nلأ..صوت مليان والبحّة دي بتعطي للصوت جمال،\nومحدش شم ريحة أجمل من ريحته، وهو أشبه الناس بإبراهيم عليه السلام،\nيبقى احنا كده عرفنا وصف رسول الله ﷺ  ووصف إبراهيم عليه السلام\nبعد ما أم معبد خلصت وصف زوجها قال لها :\nوالله ده صاحب قريش إللي بيدوروا عليه \nوأنا كنت ناوي أتبعه، وفعلا هتبعه أول ما أعرف أوصل له\nفي الطريق قبل ما يصل رسول الله ﷺ  يثرب قابل رجل اسمه بُرَيْدة بن الحصيب زعيم قبيلة أسْلم وكان معاه سبعين رجل من قومه،\nوكانوا خرجوا يبحثوا عن رسول الله ﷺ عشان ياخدوا مكافأة المائة ناقة من قريش،\nرسول الله ﷺ بكل هدوء عرض عليه وعلى قومه الإسلام\nمع إن الموقف خطير والناس دي جاية إما تقتله أو تأسره ومع ذلك رسول الله ﷺ كان همه الدعوة \nوسبحان مقلب القلوب زعيم القبيلة أسلم وأسلم معاه السبعين رجل كلهم في لحظة واحدة كده\nيعني رسول الله ﷺ قعد سنين في مكة يدعو الناس عشان يجمع العدد ده،\nفكأن الله عز وجل بيقول لنا إن احنا المطلوب نعمل إللي نقدر عليه فقط،\nالهداية والتوفيق وتقليب القلوب دي حاجة بتاعة ربنا\nكان خبر خروج رسول الله ﷺ من مكة وصل للأنصار في المدينة، فكانوا بيخرجوا ينتظروه على أبواب يثرب،\nلأنهم مكنوش عارفين الوقت المحدد إللي هيوصل فيه رسول الله ﷺ، \nوده لأنه كان ماشي من طريق غير الطريق المعروف، وكان بيخرج معاهم اليهود إللي كانوا ساكنين في يثرب.\nنشوف كده عالسريع اليهود دول جاءوا منين أصلا؛\nلأن هيكون في احتكاك بينهم وبين المسلمين وبين رسول الله ﷺ كثير، وخصوصا إننا كنا سايبينهم في الشام بعد رفع عيسى عليه السلام فإيه إللي جابهم يثرب\nاليهود كانوا بيطاردوا أتباع عيسى عليه السلام وبيعذبوهم وبيحرضوا عليهم الملوك وخصوصا الحواريين،\nفربنا سلط عليهم إللي يقتلهم ويعذبهم، في قصة طويلة ملك من ملوك الرومان حاصر اليهود في القدس وصمم إنهم ينزلوا على حكمه،\nولما استسلموا له أمرهم إنهم يقتلوا بعض، كل رجل يقتل أهله وإللي هيتبقى في النهاية هيسيبه يعيش،\nوفعلا اليهود بدأوا يقتلوا بعض الرجل يقتل زوجته وأولاده مجزرة بشعة\nفهرب إللي عرف يهرب وقُتل إللي قُتل، ولم ينجوا من المجزرة دي إلا الشريد ، يعني إللي كان برة البلد أصلا في مكان بعيد،\nفبدأ يتجمع اليهود المشردين على هيئة مجموعات وسكنوا يثرب واستقروا بها واختاروا أخصب الأماكن وسكنوا فيها وبنوا الحصون،\nومن هذه المجموعات:\nيهود بني قَيْنُقاع، ويهود بني النُّضِير، ويهود بني قُرَيْظة وغيرهم، وكانوا بالمئات، وكان عندهم خبرات بالزراعة والصناعة وبناء الحصون،\nوده كان سبب ازدهار الزراعة وانتشار البساتين في يثرب،\nبعد انهيار سد مأرب وحصول السيل هاجرت القبائل اليمنية ومنها قبيلة الأَزْد إللي كان منها الأوس والخزرج،\nفجاءوا ليثرب بعد اليهود فاضطروا إنهم يسكنوا الأماكن المهجورة في يثرب، لأن الأماكن الخصبة سكنها اليهود،\nوطبعا اليهود خافوا على نفسهم\nفقعدوا يوقعوا بين الأوس والخزرج عشان ميتحدوش ضدهم، نظام فرّق تَسُد\nوفعلا قامت بينهم الحروب وكان آخرها يوم بُعاث إللي كان قبل الهجرة بفترة،\nفلما فهم العرب خطة اليهود بعد سنين طويلة من القتال وإنهم كده هيفنوا بعض والمستفيد من الموضوع هم اليهود فعملوا صُلح واتفقوا على رجل اسمه عبد الله بن أُبَي بن سلول يكون هو حاكم المدينة،\nلكن حصلت بيعة الأنصار وكل الأمور اتغيرت\nوصل رسول الله ﷺ وأبو بكر الصديق رضي الله عنه لحدود يثرب إللي هيكون اسمها المدينة النبوية بعد ما رسول الله ﷺ هيدخلها،\nوبكده انتهت فترة الدعوة في مكة،\nانتهت ثلاثة عشرة سنة من البناء والتأسيس لعقيدة المسلمين، وبناء أخلاقهم،\nانتهت مرحلة التعذيب والسخرية والتعدي على رسول الله ﷺ  والمسلمين،\nواتعلم الصحابة درس مهم جدا في السنين دي وهو إن الطريق إلى الله مش مفروش بالورود،\nوإن المسلم ربنا لن يُمكّن له في الأرض إلا لما يُبتلى ويواجه الابتلاء بالصبر والثبات\nأيوة كانت فترة صعبة لكن برده كان فيها إيمانيات وسعادة عاشها الصحابة مع رسول الله ﷺ، \nودي رسالة من ربنا إن مفيش حاجة بتستمر، كل بلاء هيعدي،\nلكن يا ترى لما يعدي هيأخذ معاه إيه لربنا،\nهل هيأخذ معاه الصبر والثبات ولا هيأخذ معاه التسّخط وعدم الرضا والجزع\nهنشوف إن شاء الله أثر تربية رسول الله ﷺ للصحابة خلال الثلاثة عشرة سنة دي هتكون عاملة إزاي،\nانتهت فترة العهد المكي وهتبدأ فترة العهد المدني\nإزاي رسول الله ﷺ بدأ حياته في المدينة النبوية، وإيه الأُسس إللي وضعها في المدينة ؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 75, "l": "الجزء 49 | استقرار رسول الله في المدينه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_التاسعة_والأربعون\n#استقرار_رسول_الله_في_المدينة\nكنا وافقين المرة إللي فاتت عند وصول رسول الله ﷺ ليثرب، وقلنا إن الأنصار كانوا بيخرجوا ينتظروا رسول الله ﷺ كل يوم الصبح لأنهم مكنوش عارفين الوقت إللي هييجي فيه بالضبط،\nفكان أول ما الحر يشتد يرجعوا بيوتهم، ففي يوم لما رجعوا بيوتهم، كان في واحد من اليهود موجود فشاف حد جاي من بعيد فبدأ ينادي على الأنصار،\nفتجمع الأنصار مرة ثانية وشافوا رسول الله ﷺ وأبو بكر قادمين،\nوالأنصار مكنوش يعرفوا رسول الله ﷺ ولا شافوه قبل كده، إللي يعرفوه إللي قابلوه في مكة فقط في البيعة،\nفكانوا بيقولوا هو إللي على اليمين ولّا إللي على الشمال\nفوهم حيرانين كده قام أبو بكر الصديق بتظليل رسول الله ﷺ من الشمس فعرفوا مَن هو رسول الله ﷺ \nأول ما قرّب منهم قعدوا يقولوا جاء رسول الله ..جاء نبي الله، وطبعا محدش قال طلع البدر علينا دي خالص\nمفيش ولا رواية صحيحة بتقول إن الأنصار استقبلوا رسول الله ﷺ بإنشادهم طلع البدر علينا\nوفي رواية بتقول إن وصل عدد الأنصار إللي استقبلوا رسول الله ﷺ يصل إلى خمسمائة وكانوا بيحملوا السلاح من باب التشريف والإحتفال به ﷺ، \nفدخلوا حدود المدينة في منطقة اسمها قِباء، وأحاط الأنصار بأبي بكر الصديق ورسول الله ﷺ ، والغِلمَان تفرقوا في الشوارع وقعدوا ينادوا يا محمد يا رسول الله..محمد يا رسول الله!\nوالنساء والرجال طلعوا فوق البيوت يشوفوا الموكب بتاع رسول الله ﷺ وكانوا فرحانين به جدا،\nحتى قال صحابي من الأنصار وهو البراء بن عازب:\nأنا مشفتش أهل المدينة فرحوا بحاجة زي فرحهم برسول الله ﷺ \n\"وَالَّذِينَ تَبَوَّءُوا الدَّارَ وَالْإِيمَانَ مِن قَبْلِهِمْ يُحِبُّونَ مَنْ هَاجَرَ إِلَيْهِمْ وَلَا يَجِدُونَ فِي صُدُورِهِمْ حَاجَةً مِّمَّا أُوتُوا وَيُؤْثِرُونَ عَلَىٰ أَنفُسِهِمْ وَلَوْ كَانَ بِهِمْ خَصَاصَةٌ\"\nوكان ده في يوم الإثنين الثاني عشر من شهر ربيع الأول للسنة الرابعة عشرة من البعثة.\n☆يعني الهجرة كانت في شهر ربيع مش في محرم\nالهجرة كانت في شهر ربيع، لكن ابتداء العزم على الهجرة كان في محرم،\nلأن بيعة العقبة الثانية كانت في شهر ذي الحجة وأول هلال بعد ذي الحجة هو محرم، \nفلما عمر بن الخطاب تولى الخلافة وقالوا عايزين نؤرخ للمسلمين بتاريخ، قالوا نؤرخ من بداية العزم على الهجرة،\nفدي كانت بداية التاريخ الإسلامي\nالعجيب إن إزاي الأنصار كانوا فرحانين الفرح ده كله\nإنتم عارفين معناه إيه دخول رسول الله ﷺ يثرب\nمعناه إن كل أهل الأرض بقوا أعداء أهل يثرب،\nمعناه إنهم بيعلنوا الحرب على كل العرب، \nمعناه العداء المستمر مع اليهود إللي كانوا عايشين معاهم وفي بينهم معاهدات،معناه تضحية وبذل وإنفاق وموت في سبيل الله،\nوبرغم كل ده كانوا فرحانين كده\nالأنصار مكنش همهم أي حاجة، كان همهم الثمن إللي اتفقوا عليه مع رسول الله ﷺ...الجنة\nبعد دخول رسول الله ﷺ يثرب بقى اسمها: \n《المدينة النبوية》\n☆وفي هنا فائدة \n أي مدينة يدخلها الإسلام تكون مُنوّرة، أما المدينة إللي دخلها رسول الله ﷺ  تسمى المدينة النبوية،\nوكان الصحابة والسلف بيسموها المدينة أو المدينة النبوية، حتى لما ربنا ذكرها في القرآن قال عنها المدينة،\nفإن شاء الله هيكون الاستخدام معانا إما المدينة أو المدينة النبوية\nمش بقول حرام ولا متقولوهاش\nأنا بحب بس كل حاجة تبقى بالمسطرة \nدلوقتي رسول الله ﷺ بقى هو حاكم المدينة رسمي، فأول حاجة عملها بعد دخوله المدينة كانت بناء مسجد قباء،\nفكان هو مسجد التقوى الذي أُسّس من أول يوم :\n\"لَّمَسْجِدٌ أُسِّسَ عَلَى التَّقْوَىٰ مِنْ أَوَّلِ يَوْمٍ أَحَقُّ أَن تَقُومَ فِيهِ\"\nبعد بناء المسجد جاء علي بن أبي طالب رضي الله عنه بعد ما أدى الأمانات، وجاء معه بعض المستضعفين من المسلمين،\nوانطلق بعدها رسول الله ﷺ عشان يدخل المدينة،\nفكان كل واحد بيحاول يأخذ الناقة إللي كان راكب عليها رسول الله ﷺ ويقولوا تعال عندنا عشان يضيفوه،\nفكان يقول لهم اتركوها فإنها مأمورة\n☆وهنا رسول الله ﷺ بيعلم الناس درس عملي مهم وهو إن مادام ربنا أمر يبقى لا أنا ولا أي حد من البشر يقدر يتدخل ويغير أمر ربنا\nفضلت الناقة ماشية لحد ما وصلت عند أرض فيها نخل فبركت فيها، قعدت يعني،فسأل رسول الله ﷺ عن أصحاب الأرض فلقاهم غلامين يتيمين،\nفطلب منهم إنه يشتريها، فقالوا خذها يا رسول الله هبة،\nفرفض رسول الله ﷺ وقال لازم ندفع ثمنها، فاشتراها منهم من أموال أبي بكر الصديق رضي الله عنه، \nوكان أبو بكر الصديق قد أخذ ماله كله معاه في رحلة الهجرة وكان حاطه تحت أمر رسول الله ﷺ، \nحتى أبوه سأل حفيدته أسماء بعد ما هاجر أبو بكر: \nهو أبوكم ساب لكم فلوس أد إيه لما مشي مع محمد\nفأسماء رضي الله عنها جابت كيس قماش وحطت جواه حصى وخلت جدها الأعمى يضع يده على الكيس وهي بتقول له : ساب لنا الكيس ده،\nفقال لها : والله لو ساب لكم ده يبقى ساب لكم كتير\nوفعلا أبو بكر الصديق رضي الله عنه كان ساب الكثير، ترك لهم الله ورسوله\nبعد ما اشتراها رسول الله ﷺ بدأ المسلمون يساووها عشان يبنوا عليها المسجد النبوي،\nوكان رسول الله ﷺ بيبني مع الصحابة، مكنش قاعد يتفرج من غير ما يساعد، وهو ده القائد الحقيقي،\nالقائد هو إللي يشارك جنوده في العمل مش يقعد يتفرج عليهم وهم بيشتغلوا\nخلال فترة بناء المسجد كان رسول الله ﷺ يسكن في بيت أبي أيوب الأنصاري لأن بيته كان أقرب بيت لمكان بناء المسجد،\nوكان بيته من دورين، فطلب من رسول الله ﷺ  إنه يقعد في الدور الثاني، لأنه مش هيقدر يمشي على سقف رسول الله ﷺ تحته،\nفقال له رسول الله ﷺ إن الناس هتيجي تزوره فهيكون سهل عليهم في الدور الأول،\nفوافق أبو أيوب، وسكن في الدور العلوي مع زوجته، فلما كان في ليلة من الليالي انكسرت لهم جرة ماء،\nفبسرعة نشفوا المية باللحاف بتاعهم عشان المية متنقطش على رسول الله ﷺ ومكنش عندهم غيره\nوانتبهوا إزاي هم بيمشوا فوق رأس رسول الله ﷺ\nفتاني يوم قال لرسول الله ﷺ : \nوالله يا رسول الله ما أكون على سقف إنت تحته\n \nفانت إطلع الدور إللي فوق،\nفوافق رسول الله ﷺ، \nوكان أبو أيوب لا يأكل إلا لما رسول الله ﷺ  يأكل وكان يتتبع مكان يده وياكل وراه من شدة حبه واتباعه لرسول الله ﷺ \nفي يوم قدم له طعام فيه ثوم وبصل، فلم يأكل رسول الله ﷺ من البصل والثوم، فراح أبو ايوب بسرعة لرسول الله ﷺ يسأله:\n يارسول الله!\nهو أكل البصل والثوم حرام\nفقال له رسول الله ﷺ:\nلأ مش حرام، ولكني أكرهه بسبب ريحته!\nفقال له أبو أيوب : فأنا اكره ما تكره يا رسول آلله \n☆واخدين بالكم من موقف أبو ايوب الأنصاري وإزاي إنه كان بيتبع رسول الله ﷺ حتى في الأكل،\nمجرد ما قال له إنه بيكره حاجة قال له أنا كمان بكرهها،\nكده بكل بساطة، \nوهنشوف بعدين إن شاء الله موقف جميل جدا لأبي أيوب الأنصاري لدرجة إنه هينزل فيه قرآن\nقبل ما يكتمل بناء المسجد النبوي مات أسعد بن زرارة \nأسعد إللي بايع بيعة العقبة الأولى وكان بيأخذ مصعب بن عمير ويطوف به على الناس ويدعوهم للإسلام،\nوهو كان أول واحد جمع المسلمين في بيته لصلاة الجمعة،\nأسعد إللي بايع بيعة العقبة الثانية وكان نقيب من النقباء الاثنا عشر، مات أسعد بالذّبحة أو بالشهقة،\nمات أسعد ورسول الله ﷺ لسه في بداية المشوار، لكنه كان ناوي يُوفي ببيعته\nاشترك الجميع في بناء المسجد النبوي وكان بسيط جدا في بنائه، وكان كل مسلم بيشيل طوبة طوبة وكان عمار بن ياسر بيشيل طوبتين طوبتين فلما رآه رسول الله ﷺ  قال :\n\"وَيْح عمار تقتله الفئة الباغية\"\nوهنا رسول الله ﷺ بيحكي عن حاجة هتحصل بعد سنين وسنين من موته، بيحكي عن معركة هتحصل بين أصحابه\n☆إن شاء الله لو كان في العمر بقية نبقى نشرح القتال إللي حصل ده كان إيه وسببه إيه\nاستمر بناء المسجد فترة وبُنِي لرسول الله ﷺ حجرة بابها يُفتح على المسجد.\n☆لو لاحظنا هنلاقي إن أول حاجة رسول الله ﷺ كان بيعملها هي بناء المسجد ودي مش حاجة عشوائية نهائي\nالمسجد له دور مهم جدا في حياة المسلمين عشان كده أعداء الإسلام بيحاولوا يبعدوا المسلمين عن المساجد ويقفلوها \nالمسجد مش بس عشان الصلوات الخمس،\nالمسجد دوره إنه يحافظ على إيمان المسلمين، ويحفظ لهم دينهم، \nتخيلوا لما واحد ييجي يأخذ قرار في المسجد إللي هو بيت رب العالمين، هل يقدر يأخذه والقرار ده فيه معصية،\nلأ طبعا\nوكمان التقاء المسلمين كل يوم خمس مرات ده يقوي الروابط بينهم، فلو مرض أو حصل له مشكلة هتعرف بسهولة لأنه غاب عن الصلاة،\nده غير إن المسجد بيذيب الفروق الطبقية، يعني تلاقي الحاكم يصلي جنب المحكوم ويتعاونوا مع بعض على الخير من غير ما حد فيهم يبص ده مركزه إيه،\nوالمسجد مدرسة لتعليم المسلمين كل أمور حياتهم، هنشوف إزاي إن قرار الحرب كان بيتاخد من المسجد، \nواستقبال الوفود كان في المسجد، وكتابة المعاهدات كانت في المسجد، وتربية الأطفال ومكان لإعلان أفراح المسلمين،\nللأسف إللي يبص للواقع بتاعنا دلوقتي يلاقي إن حتى الخمس صلوات مبقوش موجودين \nومش معنى الكلام إننا نحول المسجد لدار ضيافة ومحكمة ومستشفى\nالمقصود إن تربية المسجد مطلوبة، لأن إللي مش بيراعي حق الله، مش هيراعي ولا هيعرف للبشر حقوق واحنا شايفين بعنينا\nبعد بناء المسجد ..مركز القيادة ..بدأ رسول الله ﷺ يشوف  الأوضاع المحيطة به وهيتعامل معاها إزاي، وكمان الناس إللي ساكنين حول المدينة إيه نظامهم،\nعندنا كده ثلاث مجموعات في البلد، \n◇المجموعة الأولى هي مجموعة المسلمين وفيها خمس طوائف:\n ¤الطائفة الأولى:\n كانت المسلمين من المهاجرين إللي جاؤوا من مكة ومعهمش أي مال ولا زاد ولا لهم بيت يقعدوا فيه،\n¤والطائفة الثانية: كانت الأنصار أهل البلد الأصليين وكانوا من الأوس والخزرج،\n¤الطائفة الثالثة: كانت المسلمين إللي كانوا موجودين في الحبشة بقالهم سنين،\n¤والطائفة الرابعة:\nالمسلمين المتفرقين في القبائل وكانوا بُعاد عن المدينة وهم أعِزة في قبائلهم،\n¤الطائفة الخامسة: كانت المسلمين المستضعفين في مكة إللي معرفوش يهاجروا.\n◇المجموعة الثانية : طائفة المشركين من الأوس والخزرج، كان في لسه ناس من الأوس والخزرج على شركهم،\nوالمشركين من الأعراب إللي حول المدينة، ودول كانوا عايشين على السرقة والنهب وقطع الطريق،\nفإزاي رسول الله ﷺ هيتعامل مع الناس دي\nولسه كمان المشركين من قريش، ماهم مش هيسيبوا رسول الله ﷺ والمسلمين في حالهم \n◇المجموعة الثالثة : مجموعة اليهود بمختلف قبائلهم، واليهود معروف عنهم الغدر والخيانة وهم في الوقت ده كانوا أقوياء وعندهم الأموال والسلاح.\nوفي مجموعة رابعة هتظهر بس مش دلوقتي، لما يظهروا هنتكلم عنهم إن شاء الله.\nفتخيلوا إن رسول الله ﷺ مطلوب منه يكوّن دولة يجمع فيها طوائف المسلمين المختلفة ، وإللي كل واحد منهم عاش في بيئة مختلفة عن التاني،\nومش بس كده ، ده مطلوب منه إنه يشوف حلول وطرق في التعامل مع أصناف الناس إللي قلناهم دول\nأنا شخصيا دماغي لفت من شرح المشاكل إللي واجهها رسول الله ﷺ ، فما بالكم بيه هو كان وضعه إيه\nعشان تعرفوا بس إن الدين إللي الناس بتفرّط فيه بكل سهولة ده موصلناش على طبق من فضة، ده كان في مشاكل وحوارات وخطط وتفكير،\nرسول الله ﷺ مكنش معاه عصا موسى يضرب بها المشكلة فتنفلق عن حل\nوكمان فوق ده كله حصلت أزمة في المدينة\nالمسلمين المهاجرين أصابتهم الحمى، بسبب اختلاف طبيعة الجو، في المدينة عن مكة\nفتحرك الحنين بداخلهم لمكة، فرسول الله ﷺ دعا الله عز وجل أن يحبب المدينة لنفوس المهاجرين كحب مكة بل أشد،\nودعا إنه يرفع عن أصحابه الحمى، فاستجاب الله دعاء رسول الله ﷺ وأصبح الصحابة يحبون المدينة أكثر من حبهم لمكة، ورفع الله عنهم الحمى.\nإيه بقى الخطوات إللي رسول الله ﷺ عملها عشان يعالج المشاكل إللي واجهته في بداية بناء الدولة الإسلامية\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 76, "l": "الجزء 50 | تأسيس الدوله الاسلاميه في المدينة", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخمسون\n#تأسيس_الدولة_الإسلامية_في_المدينة\nكنا واقفين المرة إللي فاتت عند المشاكل إللي واجهت رسول الله ﷺ والمفروض إنه يتعامل معاها عشان يقدر يقيم دولة إسلامية تكون مركز تنطلق منها الدعوة لكل أنحاء الأرض،\nفلازم يتعامل بحكمة لأن المرحلة دي مهمة جدا لأن هي الأساس ولازم الأساس يكون متين وقوي عشان البناء إللي هيتبنى ميقعش بعدين\nخلونا نشوف رسول الله ﷺ اتعامل مع المشاكل دي إزاي،\nأول وأهم مجموعة بالنسبة لرسول الله ﷺ هي مجموعة المسلمين بطوائفها الخمسة،\nأول طائفة المسلمين من الأوس والخزرج، ودول كان بينهم حروب من زمان لسه منتهية قريب بس لسه النفوس شايلة من بعض،\nفرسول الله ﷺ من أول ما دخل المدينة أعطاهم درس عملي قبل ما يتكلم في أي حاجة حاجة معاهم إللي هو التربية بالقدوة،\nلما وصل لمكان بناء المسجد النبوي سأل :\nأي دار أهلنا أقرب؟\nفقالوا له : دار أبو أيوب الأنصاري، فنزل عنده زي ما شرحنا المرة إللي فاتت،\nفرسول الله ﷺ من قريش وقريش من العدنانيين، والأوس والخزرج من القحطانيين، يعني فرعين كبار جدا ومختلفين تماما عن بعض،\nفرسول الله ﷺ إللي هو بعيد جدا عنهم في النسب بيقول عليهم أهلنا، فمن باب أولى إن الأوس والخزرج يعتبروا نفسهم أهل\nفدي كانت الخطوة الأولى ، الخطوة الثانية إنه قعد مع الأوس والخزرج وبدأ يعلمهم إن إللي بيربط المسلمين ببعض هو رباط العقيدة، مش القبلية أو أي حاجة تانية،\nورسول الله ﷺ كان معتمد على صدق إيمان الأنصار في تنفيذ إللي هيقول لهم عليه،\nواستجاب الأوس والخزرج وتغيرت قلوبهم ونسيوا كل إللي كان بينهم وتوحدوا مع بعض عشان هدفهم الرئيسي بناء الدولة الإسلامية\n☆ونتعلم من الموقف ده إن إللي عايز يحقق هدف مينفعش يكون في بين الشركاء مشاكل وبغضاء، وكل واحد عايز يثبت نفسه وينتصر على الثاني لأن كده القضية هتضيع، \nوانتم شفتم بعينكم في السنين إللي فاتت أثر العداوة بين أطراف معينة وصلتنا لإيه\nلازم نصفي النية ويكون همنا وقضيتنا واحدة، غير كده النتيجة هتكون الفشل،\nلأن لما الأوس والخزرج نسيوا إللي كان بينهم من المشاكل ووحدوا هدفهم وبقت قضيتهم نصرة الإسلام نجحوا في كده،\nفأي حد هيعمل عكس إللي الأوس والخزرج عملوه هيفشل فشل ذريع واحنا شايفين الواقع بتاعنا\nكده حلينا مشكلة أول طائفة، الطائفة الثانية من المسلمين دي مشكلتها مشكلة\nناس معندهمش لا مال ولا بيت ولا زاد ولا أي حاجة خالص، عشان نقرب المعنى بلغة عصرنا ممكن نقول عليهم لاجئين\nومعروف إن الإنسان إللي بيهاجر من بلده بيحس بشيء من الذِّلة والضعف فمحتاج تطييب خاطر، \nوهم أصلا لولا الإسلام كان زمانهم قاعدين في بلدهم مرتاحين مُعززين،\nوالمشكلة الأكبر إن شغلتهم في مكة كانت التجارة، وفي المدينة مفيش تجارة،\nفي زراعة لأن المدينة أرض خصبة تنفع للزراعة ومكة أرض صخرية، فحتى مفيش شغل يشتغلوا، فكان موقفهم محرج جدا\nطيب إيه الحل بقى\nرسول الله ﷺ عمل حاجة جديدة وطبعا كل ده بوحي لأن رسول الله ﷺ لا ينطق عن الهوى،\nوبرده مش معنى إن كل حاجة بالوحي إن رسول الله ﷺ  مجرد آلة وخلاص،\n لا...هو بيفكر ويخطط وكله إلهام من ربنا،\nولو حصل أي خطأ بشري الوحي بينزل عشان يعدل الخطأ ده،\nعشان بس الناس إللي كل ما نقول لهم ده رسول الله ﷺ عمل كذا يقولوا أيوة ده رسول الله المؤيد بالوحي،\nوكأن رسول الله ﷺ كان بيعمل حاجات خارقة\nاحنا شفنا بالتفصيل إزاي كان بيخطط ويرتب ويأخذ بالأسباب إللي أي بشر يقدر يعملها\nالمهم رسول الله ﷺ آخى بين المهاجرين والأنصار، يعني كل واحد من الأنصار هيبقى له أخ من المهاجرين، \nوالأخوة دي زي أخوة النسب يعني إللي يموت يورث الثاني،\nموضوع الورث ده هيُنسخ بعدين لكن دلوقتي بقى فيه أخوة زي أخوة النسب،\nوكان ربنا بيهون عليهم في القرآن :\n\"فَالَّذِينَ هَاجَرُوا وَأُخْرِجُوا مِن دِيَارِهِمْ وَأُوذُوا فِي سَبِيلِي وَقَاتَلُوا وَقُتِلُوا لَأُكَفِّرَنَّ عَنْهُمْ سَيِّئَاتِهِمْ وَلَأُدْخِلَنَّهُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ ثَوَابًا مِّنْ عِندِ اللَّهِ ۗ وَاللَّهُ عِندَهُ حُسْنُ الثَّوَابِ \"\nفكان المهاجر يفتخر بأنه مهاجر وكان الأنصاري يفتخر بأنه يأوي مهاجرا، \nومن أمثلة المآخاة إن رسول الله ﷺ آخى بين عبد الرحمن بن عوف من المهاجرين وسعد بن الربيع من الأنصار،\nفقال سعد بن الربيع لعبد الرحمن:\nمالي هقسمه نصفين إنت نصف وأنا نصف، وأنا عندي زوجتين شوف أي واحدة فيهم تعجبك وأنا أطلقها، ولما تنتهي العدة بتاعتها، إنت تتزوجها\n☆بكل بساطة قال له يقسم المال إللي هو تعب فيه سنين عشان يجمعه، مع إن الانصار بصفة عامة فقراء،\nيعني هم مكنوش أغنياء بحيث عندهم الفائض إللي يخليهم ينفقوا الأموال دي كلها\nوكمان سعد كان عنده استعداد يترك واحدة من زوجاته لأخيه،\nومش مثلا قاله خذ فلانة، يعني كانت ممكن تكون مزهقاه فيخلص منها، لأ ده بيقول له اختار، طيب افرض اختار أحب واحدة لسعد بن الربيع\nالواحد مش متصور الناس دي كانت بتفكر إزاي وجابت الإيمان ده كله منين وهم لسه مسلمين لسه من سنتين ثلاثة،\nلكن هو اليقين والرغبة الصادق في الجنة،\nعندهم استعداد يضحوا بأي حاجة مهما كانوا بيحبوها في سبيل رضا الله والجنة\nوهو ده طريق الجنة، تضحية وبذل وابتلاءات، لكن إللي عايز يعيش الدنيا كأنها جنة ويعمل فيها إللي هو عايزه ويعيش حياته كده بالطول والعرض وكمان يدخل الجنة في الآخرة ده أكيد مش فاهم حاجة\nتخيلوا واحد قعد يحوّش ويحرم نفسه لحد ما جمع ملايين وراح عشان يشتري جوهرة نادرة،\nالبائع هيبعها له ولّا لأ؟\nأكيد هيبعها له، ماهو دفع الثمن\nلكن لو واحد عاطل مش بيشتغل ومعهوش أي أموال وراح طلب نفس الجوهرة هل البائع هيعطيها له؟\nطبعا لأ لأنه مدفعش الثمن\nمينفعش المساواة بين الإثنين وربنا من صفته العدل، \nوشوفوا ربنا بيقول إيه:\n\"أمْ حَسِبَ الَّذِينَ اجْتَرَحُوا السَّيِّئَاتِ أَن نَّجْعَلَهُمْ كَالَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ سَوَاءً مَّحْيَاهُمْ وَمَمَاتُهُمْ ۚ سَاءَ مَا يَحْكُمُونَ \"\nفكل حاجة لها ثمن وكذلك الجنة لها ثمن، إللي مش هيدفع ثمن الجنة مش هيدخلها\nأنا بتكلم كقاعدة عامة وعن الناس إللي هيدخلوا الجنة من غير سابقة عذاب ولا عقاب\nمش بتكلم عن الحالات الشاذة ولا عن الناس إللي ربنا هيطلعهم من النار وهم متفحمين ولا غيرهم،\nأنا بتكلم عن إللي مجرد ما يموت يدخل الجنة على طول\nفقال له عبد الرحمن بن عوف رضي الله عنه: \nبارك الله لك في أهلك ومالك، انت بس وريني السوق بتاعكم فين\n☆وعبد الرحمن بن عوف بيضرب لنا المثل في العفة عما في أيدي الناس\nهو جاي مش معاه أي حاجة، مقلش يلا بقى فرصة فلوس وزواج جاي لي ببلاش وكمان أنا مطلبتش ده هو إللي عرض\nبنفس راضية\nهو أخذ بالأسباب وتوكل على الله وإن هو الرازق عشان يبحث عن أي دخل له،\nورسول الله ﷺ يقول: \n\"ما أكل أحدٌ طعامًا قط خير من أن يأكل من عمل يديه\"\nفدلّوه على مكان السوق عندهم، وكان سوق بني قينقاع، فتاجر في السوق وربح، ومعداش كم يوم إلا وتزوج، كل ده بسبب عفته وصدق توكله على الله\nفبعد ما تزوج رآه رسول الله ﷺ وعليه أثر صُفرة من الزعفران تضعه النساء،\nفرسول الله ﷺ قال : إيه مالك!\nفقال له تزوجت يارسول الله\nفقال له: وإنت أعطيتها مهر إيه؟\nفقال عبد الرحمن بن عوْف: وزن نواة من ذهب، يعني أعطاها خمس دراهم من ذهب،\nفقال رسول الله ﷺ  له: بارك الله لك ، اعمل وليمة ولو بشاة،\nيعني اعمل أكل لأصحابك،\nفالسنة إن لما حد يتزوج نبارك له والرجل العروس يعمل وليمة على أد مقدرته\nفكان الحل لمشكلة المهاجرين إن يكون في بينهم وبين الأنصار أخوة، يسكنوا ويأكلوا معاهم، وقال الأنصار لرسول الله ﷺ: \nيا رسول الله اقسم بيننا وبين المهاجرين النخيل!\nفقال رسول الله ﷺ  : لا! \nعشان ميعملوش حاجة وييجوا يندموا عليها بعدين \nفقال الأنصار للمهاجرين : خلاص إنتم تشتغلوا معانا في الزراعة ونتقاسم الثمار،\nفوافق المهاجرون، وبدأ الأنصار يعلموهم الزراعة لحد ما تعلموا منهم،\nوكانوا يتناوبون في طلب العلم من رسول الله ﷺ  وبين العمل، \nيعني ده يوم وده يوم ،زي ما كان عمر بن الخطاب بيعمل هو وأخوه من الأنصار،\nيعني المهاجرين مقعدوش بقى وقالوا الأنصار يصرفوا علينا وهم عندهم الأموال واحنا مش بنفهم في الزراعة وشغلتنا في التجارة،\nلأ...دول اتعلموا وساعدوا وتعبوا\nوكان السبب إللي جعل المهاجرين يهاجروا والأنصار يؤوهم وينصروهم هو الإيمان الراسخ بالله والإيمان بالبعث والإيمان بالجزاء من عند رب العالمين\nفاللي عايز يثبت على الدين ويبقى سهل عليه إنه يتنازل عن أي شيء بيحبه لله وخصوصا لو معصية يقوي إيمانه بالله ويقوي إيمانه بالبعث وبالجزاء يوم القيامة \nالطائفة الثالثة من المسلمين هم المسلمين الموجودين في الحبشة، أرسل لهم رسول الله ﷺ وطلب من بعضهم الرجوع للمدينة والأكثرية بقيادة جعفر بن أبي طالب يفضلوا موجودين في الحبشة وميرجعوش\n☆طيب ليه؟\nمش المسلمين بقى لهم دولة دلوقتي ما يرجعوا وحتى يكون لهم دور في بناء الدولة الإسلامية\nاحنا دلوقتي في بداية بناء الدولة الإسلامية، وقريش مش هتسكت والمشركين واليهود داخل وخارج المدينة مش هيسكتوا،\nفوضع المسلمين في المدينة دلوقتي خطر،\nوممكن يتعرضوا للاستئصال، يعني ممكن يجتمع المشركين كلهم ويبيدوهم، وفعلا هيتعرضوا لموقف زي كده بعدين زي ما هنشوف إن شاء الله،\nفلو كل المسلمين اتبادوا مين إللي هينشر الإسلام\nفلازم نخلي مجموعة احتياطي في مكان آمن بعيدة عن أي مشاكل لحد ما الأوضاع تستقر في المدينة ،\nويطمئن رسول الله ﷺ إن بقى للمسلمين قوة تمنعهم من إنهم يُبادوا\nزي المثل إللي بيقول : لا تجعل كل البيض في سلة واحدة\nأما المسلمين في القبائل المتفرقة فخلاهم رسول الله ﷺ زي ما هم، ولم يأمرهم بالهجرة، لأنهم في قبائل بعيدة رسول الله ﷺ مش هيقدر يوصل لها الدعوة،\nفهم مكان رسول الله ﷺ، لهم دور في مكانهم خليهم يدعوا في الناس،\nوكمان لو طلب منهم رسول الله ﷺ إنهم ييجوا للمدينة دلوقتي المشركين هياخدوا بالهم إن في حركة في المدينة وهيلفت الأنظار للمدينة وممكن يحفزهم لحرب المسلمين وهم لسه في البداية ومش مستعدين\nفالمصلحة إنهم يفضلوا مكانهم هم كمان لحد ما الاوضاع تستقر،\nالطائفة الأخيرة من المسلمين كانت المسلمين المستضعفين في مكة وإللي مش عارفين يهاجروا،\nدول رسول الله ﷺ أمرهم إنهم يكتموا إيمانهم على أد ما يقدروا ولا يجهروا بإسلامهم نهائي لحد ما ربنا ييسر لهم الأمور لأن المشركين ممكن يقتلوهم \nخلصنا مجموعة المسلمين بطوائفها المختلفة ندخل في مجموعة المشركين إللي كانوا في المدينة \nخطة رسول الله ﷺ معاهم إنه يدعوهم للإسلام ويحسن إليهم، وإنه يتجنب أي صِدام معاهم وكمان يتعاون معاهم في المصالح المشتركة بينهم\nدي كانت خطة رسول الله ﷺ ، المشركين بقى كان موقفهم إيه منه\nكبداية كده في مشركين أول ما سمعوا عن مجيء رسول الله ﷺ سابوا المدينة ومشيوا،\nزي واحد اسمه أبو عامر الراهب عبد عمرو بن صيفي،\n الرجل ده كان بيقول إنه راهب وعنده علم وإنه كان على الحنيفية دين إبراهيم عليه فقابل رسول الله ﷺ لما جاء للمدينة وسأله: \nهو إيه الدين بتاعك إللي انت جيت بيه ده\nفقال له رسول الله ﷺ: أنا جئت بالحنيفية دين إبراهيم !\nفقال له أبو عامر: أنا عليها\nفقال له رسول الله ﷺ: لا إنت مش على الحنيفية!\nيقصد يعني إن في تحريف كبير في الديانة إللي إنت عليها دلوقتي،\nفقال له أبو عامر: لأ أنا عليها، وإنت إللي أدخلت في الحنيفية ما ليس فيها\nفقال له رسول الله ﷺ: أنا معملتش كده بالعكس أنا جئت بها بيضاء نقية\nراح أبو عامر قايل له:\nيارب الكذاب يموت طريد غريب وحيد\nهو بيعرّض برسول الله ﷺ وبيتهمه بالكذب وإن ربنا هيميته طريد غريب ووحيد، \nفرسول الله ﷺ قال : أيوة صح، الكاذب ربنا يعمل يعمل فيه كده فعلا\n☆يعني أنا مش فاهم الرجل ده إيه والله\nبيتهم رسول الله ﷺ إللي قابل الأنبياء وصلى بهم وقابل إبراهيم عليه السلام نفسه، وبينزل عليه الوحي بالكذب وإنه أدخل في الحنيفية ما ليس فيها\nمحدش يزعل يا جماعة لما تلاقوا ناس بتتعدى عليكم ومش عارفين قيمتكم وهم شايفين نفسهم على حق،\nافتكروا قصة رسول الله ﷺ مع أبو عامر الراهب ده،\nواحنا هنتخطى الزمن عشان نعرف نهاية أبو عامر الراهب ده كانت إيه أو خلونا نسميه زي ما سماه رسول الله ﷺ  أبو عامر الفاسق\nلما لقى أبو عامر الفاسق الأنصار واقفين في صف رسول الله ﷺ بعد الحوار ده معاه، وبيعاملوه كزعيم مقدرش يستحمل الوضع فخرج من المدينة وراح عاش في مكة،\nوقعد فيها لحد فتح مكة، وبعدها هرب للطائف ولما أسلم أهل الطائف هرب من الطائف وعاش في الشام وهناك مات طريدا غريبا وحيدا\nعارفين بقى أبو عامر ده يكون مين ابنه\nعارفين حنظلة الصحابي المشهور إللي غسّلته الملائكة في غزوة أحد واتعرف بعد كده بغِسّيل الملائكة،\nأهه حنظلة ده يبقى ابن أبو عامر الراهب \nوإن شاء الله هنعرف قصته لما ييجي وقتها \nفأبو عامر وأمثاله خرجوا من المدينة خالص وكانوا بضعة عشرة رجلا،\nأما باقي المشركين ففضلوا قاعدين في المدينة وعلى رأسهم عبد الله بن أبي بن سلول،\nالرجل إللي كان الأوس والخزرج اتفقوا عليه عشان يكون هو الملك على المدينة، وكان رجل شريف وزعيم في قومه الخزرج  وكان غني وعنده سُلطة، \nفكان هيبقى أول ملك للمدينة ، لكن كل حاجة اتغيرت لما حصلت البيعة من الأنصار،\nوالزعامة والرئاسة راحت لرجل غريب لا هو من الأوس ولا الخزرج، وده في عرف العرب مستحيل\nإزاي رجل من قبيلة يبقى رئيس قبيلة ثانية، ينفع واحد ييجي من أدغال أفريقيا ويبقى رئيس لأمريكا \nأهه بالضبط كان ده الوضع بالنسبة لرسول الله ﷺ، فالرجل بقى عنده حقد رهيب على رسول الله ﷺ، \nوطبعا لم يُسلم، قعد يراقب الأوضاع في المدينة وهو بيغلي من جواه،\nومكنش بيفوّت فرصة ممكن يؤذي بها رسول الله ﷺ إلا واستغلها، وهنشوف أمثلة من أذيته لرسول الله ﷺ \nأما باقي المشركين فكانوا على الحِياد،\nيعني لا مع ولا ضد،\nودول كان الصحابة بيمارسوا معاهم الدعوة بكل لطف وكان رسول الله ﷺ بيُحسن إليهم عشان يؤلف قلوبهم ويدخلوا الإسلام.\nأما المشركين خارج المدينة فكان التعامل معاهم إما عن طريق دعوتهم للإسلام، أو إنه يعمل معاهم معاهدات أو إنه هيبعث سرايا حول المدينة عشان يعرّف المشركين إن المسلمين فيهم قوة،\nوالسّرِيّة معناها مجموعة عسكرية رسول الله ﷺ يُرسلها حول المدينة عشان يثبت قوة المسلمين،\nأو للجهاد في سبيل الله في أماكن بعيدة زي ما هنشوف إن شاء الله بعدين\nاتبقى عندنا عندنا مشركي قريش، ومجموعة اليهود ودول لهم قصة تانية خالص مش هينفع نقولها دلوقتي \nالسنة الأولى من الهجرة مليانة بالأحداث وخصوصا في البداية، إنتم عارفين الحماس والقلق إللي بيكون في بداية أي مشروع عادي،\nفما بالكم بمشروع بناء أمة الإسلام\nبعد ما رسول الله ﷺ حل مشاكل المسلمين في المدينة محتاج لهم دستور أو قوانين تنظم لهم أمور حياتهم،\nوخصوصا إن الطبائع مختلفة، يعني المهاجرين غير الأنصار فلازم يكون في قانون يمشي على الجميع\nإيه هو الدستور إللي رسول الله ﷺ  وضعه للمسلمين، ومين الرجل إللي جاء لرسول الله ﷺ وأسلم بعد رحلة طويييلة من البحث عن الحق،\nده إللي هنعرفه الجزء الجاي إن شاء الله\n☆"}, {"n": 77, "l": "الجزء 51 | موقف قريش من المدينه | سلمان الفارسي 1", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الواحدة_والخمسون\n#موقف_قريش_من_المدينة\n#سلمان_الفارسي(١)\nاتكلمنا المرة إللي فاتت عن طريقة رسول الله ﷺ في حل المشاكل إللي واجهته مع أوضاع المسلمين المختلفة،\nوإزاي حط خطة للتعامل مع المشركين،\nواتبقى لنا إننا نعرف إزاي رسول الله ﷺ اتعامل مع مشركي قريش ومع اليهود إللي معاه في المدينة،\nبالنسبة لمشركي قريش فالوضع معاهم كان خطير، لأنهم لما عرفوا إن رسول الله ﷺ هاجر للمدينة بعثوا رسالة تهديد ووعيد لعبد الله بن أُبي بن سلول إللي هو كان المفروض هيكون ملك المدينة وكان رئيس بعثة الحج لسه من كم شهر قالوا له فيها :\nإنتم آويتم صاحبنا! واحنا نحلف باللات والعزى إما إنكم تقتلتوه أو تطردوه من عندكم، يا إلا هنجيلكم بجيش ونقتلكم ونأخذ نساءكم وأبناءكم عبيد عندنا\nفالتهديد جاء على هوى عبد الله بن أبي بن سلول، بس كده، ده هو ده إللي أنا عايزه\nعمل إيه بقى عبد الله بن أُبي بن سلول، راح جمع المشركين من الأوس والخزرج وشرح لهم موقف قريش وإزاي إنهم هييجوا بجيش ويغزوا المدينة، فاحنا لازم نشوف حل،\nوأحسن حل إننا نحارب المسلمين ونطلعهم من المدينة \nاجتمع المشركون من الأوس والخزرج واجتمع المسلمون وبدايات حرب أهلية في المدينة ولسه الدولة الإسلامية في البداية\nجاء رسول الله ﷺ ووصل إليهم قبل ما القتال يبدأ وحاول يهدأ الوضع،\nلكن المشكلة إن دول مسلمين وكفار، طيب المسلمين هيذكرهم بالله وبالعقيدة و...و... وهيستجيبوا، لكن المشركين هيقول لهم إيه \nمينفعش يذكرهم بالله ولا بالجنة ولا بالنار\nفاستغل رسول الله ﷺ حاجة مهمة بيشترك فيها الطرفين\nقال لهم:\nهو تهديد قريش لكم وصل بكم للدرجة دي!\nده قريش مكنتش هتقدر تعمل فيكم إللي إنتم هتعملوه في نفسكم لو تقاتلتم\nمش إنتم إللي قريش تخدعكم بخدعة مكشوف كده!\nإنتم عايزين تقاتلوا أبناءكم وإخوانكم؟!\nفرسول الله ﷺ حرك فيهم روح التحدي وأثار فيهم النخوة والعزة، وذكرهم بالرحم إللي بينهم،\nوفعلا الناس هدأت وتفرقوا وانتهت المشكلة\n☆وهنا رسول الله ﷺ استغل حاجة من أخلاق الجاهلية لا تتعارض أبدا مع عقيدة الإسلام عشان يقضي بها على فتنة عظيمة كانت ممكن تحصل،\nيعني المحافظة على الوطن من أي فتن خارجية وإني أسعى لاستقرار بلدي دي حاجة الشرع يأمر بها،\nتخيلوا لما أهل البلد الواحد يقتلوا بعض إيه إللي يحصل؟\nالمستفيد طبعا من الموضوع العدو الخارجي إللي هو قريش،\nهتيجي تقضي على البقية الباقية \nوبكده يبقى احنا قدمنا للأعداء أرواحنا على طبق من فضة\nفرسول الله ﷺ قضى على الموضوع من جذوره\nقريش مسكتتش طبعا\nبعتوا للمسلمين رسالة تهديد ووعيد من باب الحرب النفسية:\nمتفكروش إنكم بعد هربتم ليثرب يبقى خلاص مش هنعرف نجيبكم\nده احنا هنجيلكم وهنبيدكم في البلد إلي انتم فيها دي\nوده حتى لو كان مجرد تهديد فمش مستبعد خالص إن قريش تبعت حد يغتال رسول الله ﷺ، \nعشان كده رسول الله ﷺ كان يبيت ساهرا من غير نوم حذرا من غدر قريش لدرجة إنه في مرة قال من شدة التعب:\nياريت ييجي رجل صالح من أصحابي يحرسني الليلة دي!\nفسمع رسول الله ﷺ  صوت فقال : مين؟\nفقال : سعد بن أبي وقاص، فقال رسول الله ﷺ: وإيه إللي جابك دلوقتي؟!\nفقال سعد:\nأنا خفت عليك يا رسول الله فجيت أحرسك\nفدعى له رسول الله ﷺ بخير، وبقى الصحابة يتنابوا في حراسة رسول الله ﷺ لحد ما ربنا أنزل آية:\n\"وَاللَّهُ يَعْصِمُكَ مِنَ النَّاسِ\"\nفقال للناس خلاص كده محدش هيقدر يقربلي ولا يؤذيني\n☆ممكن حد يسأل طيب ما كان ربنا يعصمه من الأول\nعصمة رسول الله ﷺ من الناس دي حاجة خاصة به هو،\nواحنا متفقين إن رسول الله ﷺ قدوة وإن كل إللي بيعمله لازم نعمل زيه ، فإزاي بقى نعمل حاجة خاصة بيه ربنا أعطاها له\nفكان لازم مرحلة توضح لنا بطريقة عملية إزاي القائد الإسلامي يحمي نفسه من أعدائه\nوإنه لما يكون حوله ناس تحرسه فده مش ضد التوكل أبدا،\nبالعكس ده من باب الأخذ بالأسباب،\nفربنا عصم رسول الله ﷺ من الناس بعد فترة لأن دي هتكون حاجة خاصة به واحنا محتاجين حل للناس إللي هتيجي بعده\nوعلى فكرة مكنش بس رسول الله ﷺ إللي كان بياخد حذره حتى الأنصار والمهاجرين مكنوش بيناموا ولا بيتحركوا إلا والسلاح معاهم،\nلأنهم عارفين حجم العداء إللي بينهم وبين العرب دلوقتي\nومن الحاجات إللي قريش عملتها مع أهل يثرب إللي استضافوا رسول الله ﷺ،\nإنهم قطعوا علاقتهم مع يثرب وهددت أهل يثرب بمنعهم من  الحج والعمرة ودخول مكة، \nوده عكس القوانين المتعارف عليها إن أي أحد ييجي عايز يعتمر أو يحج يُعطى الأمان ويكرم وكانت قريش بتفتخر بكده،\nلكن دلوقتي مفيش قوانين بقى واحنا هنمشي الدنيا على مزاجنا\nوشوفوا القصة إللي حصلت مع سعد بن معاذ رضي الله عنه سيد الأوس لما راح مكة عشان يعتمر حصل معاه إيه\nلما وصل مكة اتقابل مع صاحبه من أيام الجاهلية أُمية بن خلف، فقال له سعد : \nشوفلي كده ساعة البيت يكون فاضي ومفيش حوله ناس عشان أطوف بالبيت،\nفأخذه أمية وراحوا عشان يطوف بالبيت فلما طاف بالبيت قابل سعد أبو جهل\nوكان معاه أمية فسأله أبو جهل: \nهو مين إللي معاك ده يا أبا صفوان\nفقال له أمية : ده سعد\nوأبو جهل كان يعرف سعد ومع ذلك تعمد إنه يتجاهله، لأن أمية قال له سعد فقط، لو مكنش يعرفه كان قال له ده سعد بن معاذ سيد الأوس،\nفنظر أبو جهل لسعد وقال له:\nأنا شايفك بتطوف وانت آمن ولا كأنكم آويتم الناس إللي غيرت دينها محمد وأصحابه إللى غيروا وقلتم إنكم هتساعدوهم وتنصروهم\nوالله لولا إنك مع أبو صفوان مكنت رجعت لأهلك سليم\n☆ده تهديد واضح وصريح من أبو جهل بأذية سعد بن معاذ\nراح سعد رادد عليه بقوة وقايله:\nوالله لو إنت منعتني من الطواف حول البيت أنا همنع عنك ما هو أشد عليك ، همنع عنك طريق المدينة\nلأن قوافل قريش التجارية إللي هم معتمدين عليها في حياتهم لازم تعدي على المدينة، فتخيلوا لما أهل المدينة يقطعوا عليهم الطريق كده مكة هيحصل فيها أزمة اقتصادية جامدة \nفهو رد على تهديد بتهديد ، وسعد بيعلمنا إن احنا مينفعش نتذلل ولا نخضع لكافر لأن ده هيزيدهم تكبر،\nبعكس الثبات على المبدأ والوقوف بثبات وحزم قصاد الظلم والكفر فده بيهز كيان الظالم ويخوفه،\nواحنا شفنا إزاي جنود اليهود إللي معاهم أسلحة بيقفوا خايفين من أطفال مش في إيدهم غير حجارة\nوسعد بن معاذ بيعلمنا إن عشان يكون كلامنا مؤثر لازم نهدد باللي نملكه، يعني هو مهددش أبو جهل بالقتل، ولا هدده بغزو مكة ولا قال له لأ انا هاجي غصب عنك،\nهدده بحاجة تخوفه وهو فعلا بإيده يعملها وده يثبت لأبو جهل إن الأنصار صادقين في وعدهم لرسول الله ﷺ \nفأمية بن خلف لما شاف سعد بن معاذ غضب وصوته عالي قال له : مترفعش صوتك على أبا الحكم ده هو سيد مكة\nفقال له سعد : سيبك من دفاعك عنه فرسول الله ﷺ قال لنا إننا هنقتلك\nفقال أمية : في مكة ولا برة مكة\nفقال له سعد : معرفش\nفقال أمية وهو خايف : والله محمد لا يكذب \nورجع أمية لزوجته وحكى لها إللي حصل فقالت له : والله محمد لا يكذب \n☆يعني هم عارفين إنه صادق أهه ومصدقينه وبيحلفوا على صدقه\nصدق الله :\n\"وَجَحَدُوا بِهَا وَاسْتَيْقَنَتْهَا أَنْفُسُهُمْ ظُلْمًا وَعُلُوًّا\"\nبعد قطع العلاقات مع المدينة، قريش استغلت علاقاتها بالقبائل العربية وطلبت منهم إنهم يقطعوا علاقاتهم مع المدينة زي حصار اقتصادي كده،\nوكمان راسلت اليهود إللي عايشين في المدينة عشان يوقفوا تعاملتهم مع المسلمين،\nوبكده يفرضوا حصار اقتصادي داخلي وخارجي على المسلمين،\nلكن رسول الله ﷺ كان له ترتيب تاني وكان سابقهم بخطوة وعامل حسابه لموقف زي كده \nهنشوف رسول الله ﷺ  عمل إيه عشان يحل الأزمة دي بعدين إن شاء الله\nالمطلوب مننا نعرفه دلوقتي إن قريش مش سايبة المسلمين في حالهم وعمالة تؤذيهم مع إنهم بُعاد عنها،\nفهم بقى يستاهلوا إللي هيحصل فيهم بعدين\nاحنا هنرجع دلوقتي للمسلمين عشان نشوف رسول الله ﷺ بعد ما حل مشاكلهم إيه القوانين إللي هتنظم الحياة في المدينة، فبعد حل المشاكل ياتي الدستور\n◇أولا:\nإنهم أمة واحدة مفيش أي فرق بينهم نهائي.\n◇ثانيا:\nكل قبيلة تتولى أمور الدِّية بنفسها يعني المهاجرين من قريش، لو واحد من المهاجرين قتل رجل وله دِيَة يجتمع كل المهاجرين عشان يساعدوه في دفع الدّية،\nوكذلك الأنصار لو واحد من قتل رجل وله دية يجمعوا من بعض ويساعدوا أخوهم،\nولو في قبيلة لم تقدر القبيلة التانية تساعدها لحد ما يسددوا الدية\n¤معنى الدِّيَة : هو المال إللي بيُعطى لولي المقتول بدل نفسه،\nيعني لما الإنسان بيقتل خطأ يجب على القاتل إنه يدفع مال بدل النفس إللي قُتلت دي\n◇ثالثا:\nالمؤمنين يُوقفوا الظالم أو المعتدي أو الباغي منهم ، ويجتمع كل المؤمنين عليه، حتى لو كان أب أو أخ أو أي صلة قرابة،\nفأنا مش مع الظالم الباغي ده مهما كان\n◇رابعا وده خطير\nلا يقتل مؤمنٌ مؤمناً في كافر، ولا ينصر مؤمن على كافر\nمعناه إيه الكلام ده\nدلوقتي المسلمين هيدخلوا في جهاد مع إللي حواليهم من القبائل العربية، فلما واحد مسلم من الأنصار يقتل واحد كافر من المشركين وهو أخ أو ابن أو أب لواحد من المهاجرين،\nميجيش المهاجر يزعل وتأخذه الحمية ويقوم قاتل أخوه المسلم عشان قتل قريبه الكافر،\nفالإسلام وضع قاعدة إن الولاء لأخوة الدين فقط، مفيش أخوة بين مسلم وكافر حتى لو في بينهم صلة قرابة\n◇خامسا:\nمهما يحصل من خلاف بين المسلمين في شيء فلازم يرجعوا لله ورسوله عشان يحكم بينهم، وإللي يحكموا به لازم يتنفذ،\nيعني المصدر الرئيسي للتشريع هو القرآن والسنة\nدي كانت أهم القوانين إللي رسول الله ﷺ حطها عشان تنظم حياة المسلمين في المدينة،\nمن الأحداث إللي حصلت في أول الأيام إللي جاء فيها رسول الله ﷺ للمدينة،\nإن في عبد من عبيد اليهود اسمه 《سلمان الفارسي》 جاء لرسول الله ﷺ ومعاه طبق في تمر وقال لرسول الله ﷺ :\nأنا عرفت إن إنت لسه جاي البلد وإنك إنت وأصحابك فقراء فأنا جبتلكم التمر ده صدقة مني\nفرسول الله ﷺ شكره وقال لأصحابه كلوا وهو لم يأكل لأن الأنبياء حرام عليهم أكل الصدقة،\nفسلمان مشي وهو بيقول في سره : هذه واحدة\nجاء تاني يوم ومعاه طبق تاني فيه تمر فقال سلمان لرسول الله ﷺ: أنا شفتك امبارح مكلتش فجيبتلكم النهاردة التمر ده هدية \nفأخذه رسول الله ﷺ وقال لأصحابه كلوا وأكل معاهم،\nفسلمان قال في سره : هذه الثانية\nسلمان بدأ يتحرك وراح خلف رسول الله ﷺ وحاول يشوف ظهره كأنه بيدور على حاجة، فرسول الله ﷺ لاحظ إللي سلمان بيعمله فراح موقع الرداء إللي كان على كتفه فبان ظهره وظهر خاتم النبوة،\nفراح سلمان نازل على ظهر رسول الله ﷺ ومسكه وقعد يبكي بشدة\nرسول الله ﷺ مستغرب إيه في إيه، فقال له : \nتعال قصادي كده وفهمني في إيه !\nفجلس سلمان قصاد رسول الله ﷺ وبدأ يحكي له قصته\nقال له :\nأنا كنت رجل فارسي من  بلد اسمها أَصْبَهان، وكان أبي رئيس القرية، ومكنش بيحب حد زي ما بيحبني،\nوفضل حبه لي يزيد لحد ما حبسني زي البنات في البيت وخلاني أنا ملازم النار، يعني إللي قاعد جنب النار ومحافظ عليها على طول مشتعلة ومتنطفيش،\nوكان أبي عنده بستان كبير جدا، فانشغل في يوم من الأيام عن البستان بسبب إنه كان بيبني بيت له،\nفقال لي : أنا مشغول روح شوف لي أخبار البستان ،وقال لي على حاجات هو عايزها،\nوأنا ماشي عديت على كنيسة من كنائس النصارى فسمعت أصواتهم وهم بيصلوا وأنا مكنتش اعرف أي حاجة عن العالم الخارجي بسبب إني محبوس،\nفلما سمعت صوتهم وأنا ماشي دخلت أشوف إيه الناس دي وبيعملوا إيه،\nفلما شفتهم عجبتني صلاتهم وحبيت أكون زيهم، وقلت والله ده أحسن من الدين بتاعنا، وفضلت قاعد عندهم لحد ما الشمس غربت ومرحتش البستان بتاع أبي،\nفسألتهم : هو الدين بتاعكم ده أصله منين \nقالوا له : من الشام، فرجعت لأبي وكان بعت حد يدور علي وانشغل بي وساب كل أشغاله،\nفلما شافني قال : إنت كنت فين يابني\nهو أنا مش قلت لك تروح تعمل إللي قلت لك عليه\nفقلت له : يا أبي أنا عديت على ناس بيصلوا في كنيسة فعجبني دينهم، ففضلت قاعد عندهم لحد ما الشمس غربت\nفقال لي: يابني الدين ده مفيهوش خير، خليك في دينك ودينك آبائك، هو أحسن من دينهم\nفقلت له : لا والله دينهم أحسن من ديننا\nفخاف أحسن أروح أتبعهم فراح حاطط في قدمي قَيْد وحبسني في البيت، فبعثت للنصارى وقلت لهم : \nلو جاء لكم أي قافلة من الشام عرفوني، فبعد فترة جاءت قافلة من الشام فأخبروني،\nفقلت لهم: لما يخلصوا إللي جايين علشانه وخلاص هيرجعوا بلدهم قولوا لي، فلما كانوا خلاص راجعين قالوا لي، \nفخلصت نفسي من الحديد وسافرت معاهم لحد ما وصلت للشام، فسألت الناس مين أحسن واحد فقيه في الدين ده، قالوا : الأُسْقُف في الكنيسة، فروحت له وقلت له :\nالدين ده عاجبني وعايز أتبعك وأكون معاك أخدمك وأتعلم منك وأصلي معك،\nفقال لي : ادخل.\nفدخلت معه وكان رجل سوء، يأمر الناس بالصدقة ويحمسهم فلما يجمعها من الناس يحوشها لنفسه وميعطيش حاجة للمساكين،\nلحد ما جمع سبع قِلال مليانين ذهب وأموال ورقية، وأنا   كرهته جدا لما لقيته بيعمل كده، فلما مات اجتمع الناس عشان يدفنوه فقلت لهم:\nالرجل ده كان رجل سيء، كان يأمركم بالصدقة ويحمسكم ويرغبكم فلما كنتم بتجيبوا الصدقة كان بياخدها لنفسه\nفقالوا لي: وإنت عرفت منين\nفقلت لهم : أنا هوريكم الكنز بتاعه \nفأخذتهم ووريتهم مكان الكنز فطلعوا السبع قِلال ، فلما شافوا الذهب والورِق قالوا : والله ماحنا دافنينه\nوصلبوه ورجموه بالحجارة،\n وبعدين جابوا رجل تاني خلوه مكانه، فكان رجل مشفتش زيه، كان طائع زاهد متعبد همه الآخرة،\nفمحبتش حد أد ما حبيته، وقعدت معاه فترة من الزمن،\nوبعدين جاءته ساعة الوفاة، فقلت له:\nيا فلان، أنا كنت معاك وحبيتك جدا، وإنت شايف حالك دلوقتي، فتوصيني أروح لمين وتأمرني بإيه\nفقال لي:\n بص يابني، أنا معرفش حد على إللي أنا عليه ده،\nالناس بدلت وغيرت وتركوا أكثر ما كانوا عليه إلا رجل واحد ولكنه في المُوصل وهو فلان، فهتلاقيه زيي، فروح له\nفلما مات روحت الموصل لصاحبه وقلت له: \nأنا جايلك من طرف فلان هو إللي وصاني بك قبل ما يموت،\nفقال لي : خليك عندي،\nفقعدت عنده ولقيته زي صاحبه بالضبط، لكن معداش وقت طويل ومات، فسألته قبل ما يموت :\nيا فلان ، إنت شايف إللي إنت فيه، وفلان هو إللي أوصى بي إليك، فانت توصيني أروح لمين وتأمرني أعمل إيه\nفقال لي : أنا معرفش حد على إللي كنا فيه إلا رجل بنُصَيْبِين وهو فلان، فروح عنده\nفلما مات ودفناه روحت نُصيبين وحكيت له قصتي، فقال لي: خليك عندي.\nفلقيته زي صاحبيه بالضبط، لكنه مات على طول، فقلت له: يافلان، فلان صاحبك الأول كان أوصى بي لفلان، وبعدين هو أوصاني ليك، فانت توصيني أروح لمين بعدك\nفقال له : أنا معرفش حد زينا غير رجل بعَمُّورِيّة ، فلو إنت حابب روح له،\nفلما مات ودفناه، روحت لصاحبهم في عمورية وحكيت له \nقصتي، فقال لي: خليك عندي،  فقعدت عنده فلقيته على نفس منهج أصحابه واشتغلت وبقى عندي مال، لدرجة إن بقى عندي بقرات وغُنيمة، غنمة صغيرة يعني\nفجاءه الموت، فسألته : توصيني أروح لمين ، وأنا كنت جايلك من طرف فلان وفلان وفلان \nفقال :........\nهنعرف الجزء الجاي إن شاء الله قال إيه"}, {"n": 78, "l": "الجزء 52 | سلمان الفارسي 2 | رسول الله واليهود", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثانية_والخمسون\n#سلمان_الفارسي(٢)\n#رسول_الله_واليهود\nكنا واقفين عند سلمان الفارسي لما كان بيحكي لرسول الله ﷺ قصة بحثه عن الحق،\nكان وصل للرجل في عَمّورية وقعد معاه فترة لحد ما جاءه الموت، فسلمان بيحكي لرسول الله ﷺ يقول:\nقلت للرجل : يا فلان، توصيني أروح لمين بعدك، وإنت شايف حالك دلوقتي\nفقال لي: والله يابني مفيش حد على إللي كنت عليه أنا وأصحابي أنصحك تروح له، لكن الزمن إللي إنت فيه ده زمان هيخرج فيه نبي وهو هيُبعث بدين إبراهيم،\nهيخرج بأرض العرب، \nوهيهاجر لأرض بين حرّتين بينهما نخل ، له علامات لا تخفى على أحد: يأكل الهدية ولا يأكل الصدقة، بين كتفيه خاتم النبوة، فلو عرفت تروح البلاد دي روح\n☆الحَرّة يعني : أرض حجارتها سوداء \nفلما مات ودفناه قعدت في عمورية فترة، وبعدين عدّى عليّ تجار من كَلْبٍ فقلت لهم : أعطيكم بقراتي دي وغُنيمتي وتحملوني معاكم لأرض العرب\nفقالوا : ماشي اتفقنا، فأعطيتهم وأخذوني معاهم، فلما وصلنا وادي القُرى ظلموني وباعوني عبدا لرجل من اليهود\nفلما كنت عنده وشفت النخل ، تمنيت إن هي دي تكون الأرض إللي صاحبي قال لي عليها،\nفلما كنت عنده جاءه ابن عمه من قريظة فاشتراني منه وأخذني معاه للمدينة، فوالله أول ما شفتها عرفت إنها الأرض إللي صاحبي قال لي عليها وفضلت موجود فيها،\nوانشغلت بشغل الرّق ومسمعتش عن بعثة رسول الله ﷺ ولا أي حاجة خالص، لحد ما كنت في يوم شغال على نخلة من بتوع سيدي وسيدي جالس لقينا ابن عم له جاي علينا من بعيد ولما وصل عندنا لقيناه بيقول :\nقاتل الله بني قِيلة《الأوس والخزرج، وقِيلة هو اسم أمهم》 ، مجتمعين على رجل بِقُبَاء جاي من مكة بيقولوا إنه نبي\nفأول ما سمعت كلامة جسمي تلج وساب من بعضه لدرجة إني كنت هقع من فوق النخلة على سيدي \nفنزلت من على النخلة وقلت لابن عمه ده:\nبتقول إيه بتقول إيه\nفغضب سيدي وراح ضاربني وقال لي: وانت مالك أصلا بالموضوع، روح شوف شغلك\nفقلت له: مفيش حاجة أنا كنت بس عايز أتثبت من كلامه\nوكان عندي تمر جمعته، فلما جاء المساء جئتكم وقلت لكم إنكم محتاجين فدي صدقة مني، فأكل أصحابك ولم تأكل، فقلت دي أول علامة،\nوبعدين جمعت تمر تاني وقدمته لكم هدية فأكلتَ وقلت لأصحابك يأكلوا معاك، فقلت دي تاني علامة، \nومكنش فاضل غير العلامة الثالثة إللي هي خاتم النبوة فلما شفتها على ظهرك عرفت إن إنت المقصود من وصف صاحبي، فكان رسول الله ﷺ مبسوط إنه أصحابه سمعوا قصة سلمان رضي الله عنه،\nوأسلم سلمان ولكنه لسه عبد فكان مشغول في شغل الرّق.\n☆قصة سلمان من أعجب القصص إللي ممكن نسمعها مختصر القصة بتاعته : إن إللي عايز يتبع الحق بصدق وبيدور عليه ربنا هيوصله للحق في النهاية\n\"وَالَّذِينَ جَاهَدُوا فِينَا لَنَهْدِيَنَّهُمْ سُبُلَنَا\"\n¤اختلف العلماء في عُمْر سلمان الفارسي، بسبب رحلته الطويلة دي ،في ناس قالوا إنه كان من المُعَمّرين فكان عمره مائتين وخمسين سنة، وناس قالوا ثلاثمائة،\nلكن القول الراجح إنه مات لما كان قرّب على الثمانين سنة في خلافة عثمان بن عفان رضي الله عنه،\nيعني لما قابل رسول الله ﷺ كان تقريبا عمره معدي الأربعين\nوبما إننا اتكلمنا عن اليهود خلونا نشوف خطة رسول الله ﷺ في التعامل مع اليهود كانت إيه\nعارفين لما بنبقى داخلين مشروع أو بنقدم على وظيفة أو مسافرين مكان،\nالطبيعي إننا بنسأل عن طبيعة الحاجات إللي احنا هنتعامل معاها لأول مرة دي، نعرف طبيعة الناس إللي هنتعامل معاهم، مميزاتهم وعيوبهم،\nإزاي نتقي شرهم ، إزاي نتعايش معاهم ومنعرّضش نفسنا إنهم يخدعونا،\nأهه ربنا كان بيعمل كده مع رسول الله ﷺ والمسلمين من خلال القرآن\nقبل ما المسلمين يعرفوا أصلا إنهم هيهاجروا للمدينة ويتعاملوا مع اليهود كان ربنا بيحكي لهم قصص عن بني إسرائيل وعن موسى عليه السلام ومواقفه مع فرعون وكمان مواقفه مع بني إسرائيل،\nعشان ربنا يوسع آفاق المسلمين، انتم هتكون لكم دولة في يوم من الأيام، فمحتاجين تعرفوا أصناف الناس الموجودة معاكم على الأرض ومنهم اليهود،\nفربنا أراد إنه يوصل للمسلمين فكرة عامة عن بني إسرائيل، إللي هم أجداد اليهود إللي عايشين في يثرب،\nولما يدخلوا المدينة يبقى عندهم انطباع إن اليهود دول أهل كتاب زينا، وده هنلاقيه في آية :\n\"ولَا تُجَادِلُوا أَهْلَ الْكِتَابِ إِلَّا بِالَّتِي هِيَ أَحْسَنُ\"\nوكمان هم أتباع رسول زينا، موسى عليه السلام وبيعبدوا إله واحد وهو الله، وهم اتأذوا وصبروا على ظلم فرعون:\n\"وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنَىٰ عَلَىٰ بَنِي إِسْرَائِيلَ بِمَا صَبَرُوا\"\nوربنا قال عنهم إنه اختارهم على العالمين،\n\"وَلَقَدِ اخْتَرْنَاهُمْ عَلَى عِلْمٍ عَلَى الْعَالَمِينَ\"\nفكل ده بيعطي للمسلمين انطباع إيجابي عن اليهود إللي هيتعاملوا معاهم لما يتقابلوا، وخصوصا إن المنطق والعقل بيقول إن اليهود هيتبعوا رسول الله ﷺ\nلكن في نفس الوقت ربنا علّم الصحابة في القرآن إن بني إسرائيل دول برده فيهم سلبيات وعيوب،\nفلازم تكونوا على حذر، فهم سيئوا الأدب مع الأنبياء قالوا لموسى:\n\"أُوذِينَا مِنْ قَبْلِ أَنْ تَأْتِيَنَا وَمِنْ بَعْدِ مَا جِئْتَنَا \" مفيش جديد يعني\nوكمان متمردين على أوامر ربنا وبيتحايلوا عليها، زي قصة عبادة العجل وقصة أصحاب السبت إللي اتكلمنا عنهم في قصص الأنبياء،\nده غير كفرهم بالنعمة ونكرانهم للجميل، يعني فيهم العبر\nفكده الصحابة هيبقى عندهم نظرة متوازنة لما ييجوا يتعاملوا مع اليهود،\nنطمع في إسلامهم ونعاملهم بالحسنى عشان نرقق قلوبهم وفي نفس الوقت نكوت على حذر من مكرهم\nمن الحاجات إللي رسول الله ﷺ عملها عشان يرقق قلوب اليهود ويثبت لهم أننا فريق واحد من المؤمنين، إلهنا واحد قبلتنا واحدة نؤمن بكل الأنبياء السابقين إنه:\n◇كان بيصلي وقبلته لبيت المقدس، إللي هي أصلا قبلة اليهود،\nفاحنا يا جماعة متشابهين في كل حاجة اهه مش فاضل غير إنكم تؤمنوا برسول الله ﷺ فقط،\nوخصوصا إن علامات رسول الله ﷺ موجودة عندكم في التوراة، وانتم كنتم بتتوعدوا الأوس والخزرج بالنبي إللي هيظهر\n◇الحاجة الثانية :\nإن رسول الله ﷺ لما دخل المدينة عرف إن اليهود بيصوموا يوم عاشوراء، فرسول الله ﷺ سألهم : إيه اليوم إللي انتم بتصوموه ده؟\nفقالوا : ده يوم عظيم ربنا أنجى فيه موسى وقومه وأغرق فرعون وقومه، فصامه موسى شكرا لله فاحنا كمان بنصومه،\nفقال لهم رسول الله ﷺ: احنا أحق وأولى بموسى منكم، فصامه رسول الله ﷺ  وأمر الصحابة بصيامه\n طبعا الكلام ده كله \nبوحي من رب العالمين \nيعني رسول الله ﷺ مش من نفسه كده عمل التشريعات دي\n\" إِنْ هُوَ إِلَّا وَحْيٌ يُوحَىٰ\"\n☆وبما إننا بنتكلم عن عاشوراء فخذوا المعلومة دي عشان إللي ميعرفهاش يعرفها \nقال رسول الله ﷺ: \n«صيام يوم عاشوراء، إني أحتسب على الله أن يكفر السنة التي قبله»\nفخلوا في نيتكم إنكم كل سنة هتصوموا يوم عاشوراء ما دمتم على قيد الحياة، عشان لو ربنا كتب على حد فينا ظروف معينة أو كتب علينا الموت ربنا يعطينا الأجر كامل\nجمع رسول الله ﷺ اليهود أكثر من مرة واتحاور معاهم ودعاهم للإسلام، كان ساعات يكلّم القبائل مجتمعين، وساعات يكلم الأفراد، \nوكان يأتيه بعض اليهود عشان يسمعوا منه ويشوفوا هل هو فعلا النبي المذكور عندهم في التوارة ولّا لأ.\nمن اليهود إللي جاءوا لرسول الله ﷺ واحد من علمائهم،\nمن بني قينقاع اسمه عبد الله بن سَلَام،\nفدخل على رسول الله ﷺ وقال له : \nأنا هسألك عن ثلاثة أمور محدش يعرفهم غير نبي فعلا\nإيه هو أول شيء يحشر الناس، وإيه أول طعام يأكله أهل الجنة،\nوإزاي الولد ساعات يكون شبه أبوه، وساعات يكون شبه أمه وأخواله\nفقال له رسول الله ﷺ:\nالحاجات دي جبريل أخبرني عنهم قبل كده، فقال له عبد الله بن سلام : ده عدو اليهود \nفقال رسول الله ﷺ:\nأما أول شيء يحشر الناس فنار تخرج من ناحية المشرق فتحشرهم ناحية المغرب،\nوأول طعام يأكله أهل الجنة هو كبد الحوت.\n☆  في حديث تاني بيقول إن بعد ما أهل الجنة هياكلوا كبد الحوت هياكلوا ثور الجنة إللي كان بيتغذى من أطرافها بعد ما يُذبح لهم،\nمفيش حكمة ظاهرة عن السبب إللي يخلي أول حاجة أهل الجنة يأكلوها هي كبد الحوت، وبعدين لحم الثور \nلكن العلماء استنبطوا حِكم، \nقال بعضهم: إن الحوت من الحيوانات المائية التي تشير لعنصر الحياة على وجه الأرض،\nوالثور من الحيوانات البرية التي تشير إلى الحرث والكسب في الأرض، \nفلما أهل الجنة يأكلوها ده كأنه إشارة إلى نهاية الدنيا وبداية الآخرة\nأما الولد فساعات يكون شبهه لأبوه وساعات الشبه لأمه و أخواله:\nوده لمّا يسبق ماء الرجل ماء المرأة يكون الشبه لأبوه، ولو سبق ماء المرأة ماء الرجل كان الشبه لها \nفقال له عبد الله بن سلام : أشهد أنك رسول الله \nوبعدين قال :\nيارسول الله اليهود قوم بُهْت، يعني كذابين وبينكروا الحقيقة، فلو عرفوا إني أسلمت هيقولوا إني بكذب وبقول كلام مش موجود في التوراة، فأنت اسألهم عني الأول،\nفاختبأ عبد الله بن سلام داخل البيت،\nوجاء اليهود فسألهم رسول الله ﷺ عن عبد الله بن سلام : \nتقولوا إيه عن عبد الله بن سلام، إيه رأيكم فيه؟\nقالوا : \nده أعلم واحد فينا وابن أعلمنا وأحسن واحد وابن أحسن واحد فينا، وسيدنا وابن سيدنا\nفقال لهم رسول الله ﷺ: طيب إيه رأيكم لو أسلم؟\nفقالوا : أعاذه الله من ذلك\nيعني بلغتنا بعد الشر عليه\nفخرج عليهم عبد الله بن سلام وقال لهم:\nأشهد ألا إله إلا الله وأن محمدا رسول الله \nفقال اليهود:\nده شرنا وابن شرنا وأسوا واحد فينا، وقعدوا يشتموه\nفعبد الله بن سلام قعد يقول لهم : اتقوا الله انتم عارفين إنه رسول الله، آمنوا به \nفقالوا له : كذبت\nفرسول اللهﷺ قعد يهدي الأمور لحد ما مشيوا، فكده بقى الموضوع واضح قصاده ﷺ،\nهم عارفين إنه نبي لكن مش عايزين يؤمنوا به\nوده كان حال كل اليهود، عارفين إنه رسول لكن لم يؤمنوا به استكبارا وحسدا، فلم يسلم من اليهود إلا القليل\nيبقى كده رسول الله ﷺ والصحابة هيعيشوا مع اليهود في المدينة، يبقى احنا محتاجين قوانين تنظم الأمور البلد،\nعشان محدش يظلم الثاني \nنشوف القوانين أو خلينا نقول المعاهدة إللي حصلت بين رسول الله ﷺ وبين اليهود\n◇أولا: \nاليهود بقبائلهم المختلفة هيعيشوا مع المؤمنين في المدينة لكل واحد دينه الخاص،\n\"لَا إِكْرَاهَ فِي الدِّين\"\n◇ثانيا:\nالمسلمين لهم اقتصادهم الإسلامي وذمتهم المالية الخاصة بهم، واليهود لهم ذمتهم المالية الخاصة،\nفمش معنى إن الرئاسة في الدولة للمسلمين يبقى نظلمهم ونأخذ حقهم أو ناخذ ممتلكاتهم\n◇ثالثا:\nلو حصل حرب أو حصار على المدينة فيجب على الجميع  الدفاع عن المدينة المسلمون واليهود يدا بيد\n◇رابعا:\nإذا حصل حرب الكل يساهم بأمواله عشان يدافع عن البلد، ويكون بينهم النصح والبر، وينصروا المظلوم\n◇خامسا:\nلا تُجَار قريش ولا من ناصرها، بند واضح وصريح، عشان محدش ييجي بعدين من اليهود الماكرين إللي بيتحايلوا على  كل الأوامر ويقولوا لرسول الله ﷺ  أصل إنت مقلتش\nأهه بيقولها لهم واضحة وصريحة : \nتقطعوا علاقتكم بقريش، ولا تُجيروا ولا تحموا أي احد من قريش ولا أي أحد يناصر قريش\nولو قريش هجمت على المسلمين في المدينة يجب على اليهود إنهم يساعدوا المسلمين في حربهم ضد قريش،\nمش العكس\n◇سادسا:\nمفيش أي واحد من اليهود يخرج من المدينة إلا بإذن رسول الله ﷺ، زي نظام الجوازات كده، \nيعني عايز تطلع برة المدينة تروح لرسول الله ﷺ تأخذ منه تأشيرة الخروج\nليه طيب التضييق ده \nلأن اليهود ممكن يشعلوا نار الفتنة برة المدينة فيدخّلوا المدينة في مشاكل ملهاش لازمة\n◇سابعا:\nأي خلاف أو مشكلة بين اليهود والمسلمين فالحكم فيها لله ولرسوله\nالناس إللي بتقعد تقول ده الرسول عمل معاهدات مع اليهود، فاحنا كمان نعمل عادي \nحلو أوي مفيش مشاكل، لكن هل المعاهدة إللي رسول الله ﷺ عملها مع اليهود فيها أي مخالفة لشرع ربنا؟\nهو احنا مش شايفين إللي بيحصل بين المسلمين وبين اليهود دلوقتي؟\nهل اليهود المعتدين الظلمة دول ينفع معاهم عهد؟\nهل اليهود لما بيحصل بينهم وبين المسلمين خلاف بيرجعوا لشريعة الإسلام هي إللي تحكم؟\nهل اليهود لما بيكونوا عايزين يخرجوا برة البلد بيرجعوا للمسلمين ويأخذوا منهم الإذن، ولّا العكس هو إللي حاصل؟\nاعرفوا وعرفوا الناس إن رسول الله ﷺ لما عمل المعاهدة مع اليهود كانت اليد العليا للإسلام والمسلمين، \nمكنتش بالذل والإمتهان إللي احنا عايشين فيهم دول\nوهنشوف لما اليهود هيخالفوا شروط الإتفاق رسول الله ﷺ  هيعمل فيهم إيه\n¤قال يقولوا احنا عملنا معاهدة مع اليهود زي ما رسول الله عمل معاهدات مع اليهود قال\nإيه بقى موقف اليهود من شروط المعاهدة إللي رسول الله ﷺ حطها دي، \nيعني هل وافقوا ولا اعترضوا ولّا عملوا إيه\nالمفاجأة إنهم وافقوا ومحدش فيهم اعترض على حاجة، مع إن أعدادهم كبيرة ومعاهم السلاح والأموال يعني هم يعتبروا دولة مستقرة، \nبعكس الدولة الإسلامية إللي لسه في بدايتها وتعتبر ضعيفة ومحدش معترف بيها، \nفليه بقى اليهود سلموا كده لرسول الله ﷺ \nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 79, "l": "الجزء 53 | أحداث السنه الأولى من الهجره", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الثالثة_والخمسون\n#أحداث_السنة_الأولى_من_الهجرة\nكنا واقفين المرة إللي فاتت عند المعاهدة إللي رسول الله ﷺ عملها مع اليهود وشفنا القوانين إللي رسول الله ﷺ وضعها عشان ينظم العلاقة بين اليهود والمسلمين وشفنا إزاي اليهود وافقوا على المعاهدة دي، \nوكان السؤال إللي بيفرض نفسه هو : ليه اليهود وافقوا كده بكل بساطة على كلام رسول الله ﷺ من غير ما يعترضوا مع إنهم الأقوى \nموافقتهم كان لها أسباب:\n◇أولا :\n اليهود بطبعهم جبناء جدا، فلما يلاقوا إللي يواجههم بقوة ويكون ثابت على مبدأ، يخافوا ويقلقوا، وينزلوا على شروط القوي،\n\"لأَنْتُمْ أَشَدُّ رَهْبَةً فِي صُدُورِهِمْ مِنَ اللَّهِ\"\nوهم أحرص الناس على حياة، أهم حاجة عندهم إنهم يعيشوا، مش مهم العيشة عاملة إزاي لكن أهم حاجة إنهم عايشين،\n\"وَلَتَجِدَنَّهُمْ أَحْرَصَ النَّاسِ عَلَى حَيَاةٍ \"\n◇ثانيا:\nاليهود كانت قبائل متفرقة وفي تفرق كبير بينهم، فكل فريق له عداوات مع الفريق الثاني،\n\"بَأْسُهُم بَيْنَهُمْ شَدِيدٌ ۚ تَحْسَبُهُمْ جَمِيعًا وَقُلُوبُهُمْ شَتَّىٰ\"\nفرسول الله ﷺ كان عارف الفُرقة إللي بينهم دي وعارف إنهم مش هيتحدوا فكان بيتكلم بكل قوة وثبات\n◇ثالثا:\nاليهود أهم حاجة عندهم مصالحهم، فهم قبلوا بكلام رسول الله ﷺ عشان يحافظوا على مصالحهم،\nولو دخلوا في مواجهة مع الأوس والخزرج إللي بيشتروا منهم، مش هيلاقوا حد يبيعوا له، فبالتالي تجارتهم هتضيع\n◇رابعا:\nالرهبة والرعب في قلوبهم من رسول الله ﷺ  والمؤمنين\nبمعنى إن ربنا بيُلقي في قلوب اليهود الرعب من المؤمنين لما بيقابلوهم،\nودي حاجة خاصة بالمؤمنين الصادقين، والنصر بالرعب ده جندي من جنود الله رسول الله ﷺ قال :\n\"نُصرت بالرعب مسيرة شهر\"\nيعني يكون بين العدو وبين رسول الله ﷺ مسافة شهر والتاني قاعد مرعوب\n☆طيب سؤال ليه اليهود والكفار بصفة عامة مش بيخافوا من المسلمين دلوقتي\nإللي يجاوبنا على السؤال ده رسول الله ﷺ،  قال:\n\"يُوشِكُ الأمم أن تَداعَى عليكم كما تداعى الأكلة إلى قَصْعَتها»، \nفقال قائل: ومِن قِلة نحن يومئذ؟ قال: «بل أنتم يومئذٍ كثير، ولكنكم غثاءٌ كغثاء السيل، \nوليَنزِعن الله من صدور عدوكم المَهابَة منكم، وليقذِفَن في قلوبكم الوَهَن»، \nفقال قائل: يا رسول الله وما الوَهَن ؟ قال: «حب الدنيا، وكراهية الموت».\nفربنا نزع المهابة والرعب ده من قلوب أعداء المسلمين عشان المسلمين للأسف غثاء كغثاء السيل، \nوغثاء السيل يعني لما مية جارية كثيرة بتتحرك زي ما بنشوف في الفياضات،\n مش بنلاقي المية دي بتلم معاها الأوساخ والمخلفات والأعشاب اليابسة،\nفرسول الله ﷺ بيشبه عقول وطموحات وهمم المسلمين وأفعالهم وتعلقهم بالأمور التافهة بغثاء السيل ده،\nواحنا شايفين حال المسلمين عامل إزاي للأسف\nطيب بعد ما اليهود وافقوا على المعاهدة واتفقوا مع رسول الله ﷺ هل التزموا بكلامهم وعاشوا مسالمين مع المسلمين في المدينة\nلأ طبعا...عملوا كوارث..حاولوا يفرقوا بين المسلمين ويثيروا الحرب بين الأوس والخزرج وحاولوا يقتلوا رسول الله ﷺ ،\nوبقوا يشجعوا الأوس والخزرج على عدم الإنفاق ،\nهنشوف معاهم العَجب\nنرجع لرسول الله ﷺ ونشوفه إزاي اتعامل مع الحصار الاقتصادي الداخلي والخارجي إللي حاولت قريش تفرضه على رسول الله ﷺ،\nقلنا قبل كده إن قريش استغلت علاقتها بالقبائل واتصالتها مع اليهود عشان يحاصروا المسلمين اقتصاديا في المدينة،\nلكن رسول الله ﷺ كان مُتوقع حاجة زي كده،\nإيه هي أهم الحاجات إللي الإنسان بيحتاجها عشان يعيش\nالماء والغذاء\nطيب الماء موجود في أبار اليهود والمسلمون بيشتروا منهم الماء،\nطيب لو اليهود رفضوا بيع الماء للمسلمين، هتبقى مشكلة جامدة\nيبقى الحل إن المسلمين يكون عندهم بئر خاص بهم\nقال رسول الله ﷺ للمسلمين :\nمين يشتري بئر رومة وله الجنة؟\nفاشتراها عثمان بن عفان رضي الله عنه وراح لرسول الله ﷺ  وقال له إنه اشتراها، فقال له رسول الله ﷺ اجعلها سبيل للمسلمين،\nيعني هو اشتراها بآلاف الدراهم ورسول الله ﷺ قال له خليها للمسلمين ببلاش \nخدوا بالكم إن التربية الإيمانية إللي رسول الله ﷺ ربى عثمان رضي الله عنه عليها خلال السنين إللي فاتت دي هي خلت عثمان يتنازل بكل سهولة عن آلاف الدراهم إللي عاش عشان يجمعها،\nالدافع الرئيسي هو إنه يريد الحنة\nوبكده تم تأمين المصدر الرئيسي للمياه للمسلمين في المدينة،\nطيب الغذاء وباقي السلع هنجيبها منين\nهنجيبها من السوق، والسوق بإيد اليهود برده\nيبقى الحل إننا نعمل سوق موازي للمسلمين، لأن المسلمين لازم يكون لهم الاقتصاد الخاص بهم،\nافرضوا اليهود رفعوا ثمن السلع، المسلمين هيعملوا إيه\nيبقى أول حاجة عشان الدولة تقف على رجلها إنها تعتمد على نفسها في تدبير أمور معيشتها، عشان متبقاش تحت رحمة أحد\nبدأ رسول الله ﷺ مع المسلمين يبحثوا عن أرض واسعة تنفع تكون سوق، دوّروا في كذا مكان مكنش في مكان مناسب،  لحد ما جاء له رجل وقال له:\nأنا لقيت أرض مناسبة إيه رأيك تشوفها يا رسول الله\nفراح معاه رسول الله ﷺ ولما شافها عجبته وضرب الأرض برجله وقال : أيوة ده السوق بتاعكم، فمحدش ينقص من قيمته ولا حد يفرض عليه ضرائب\nيعني أي حد عايز ييجي يبيع في السوق ده ييجي من غير ما يدفع ضرائب ولا رسوم ولا أي حاجة،\nوبدأ السوق يكبر شوية شوية، أيوة هو مش زي سوق اليهود ،\nلكن على الأقل المسلمين هم المتحكمين فيه بقوانينهم وشريعتهم هم\nوبكده رسول الله ﷺ فوّت على قريش فرصة إنهم يحاصروه اقتصاديا\nاحنا دلوقتي في السنة الأولى من الهجرة، رسول الله ﷺ رتب أموره وعمل المعاهدات وبدأت الدولة تستقر،\nحصلت أحداث كثيرة في السنة دي من الأحداث إللي حصلت: إن رسول الله ﷺ تزوج بعائشة رضي الله عنها وهي ابنة تسع سنين،\nبتحكي عائشة رضي الله عنها إنها كانت بتلعب مع أصحابها على المُرجيحة فلقت أمها أم رومان بتنده عليها وهي مش عارفة عايزة إيه، \nفلما راحت لها أخذتها لحد باب البيت وأنا عمالة أنهج، فلما هديت شوية مسحت وجهي ورأسي بالماء وبعدين أدخلتني الدار، فلقيت مجموعة من نساء الأنصار في البيت وقلن: \nعلى الخير والبركة، \nفسلمتني لهن فقعدوا يعدلوا في هدومي ويهيؤوني،\nوبعدين لقيت رسول الله ﷺ داخل علينا فسلموني له ودخل بي وأنا بنت تسع سنين\n☆قلنا قبل كده مواصفات السيدة عائشة وإنها كانت طويلة وإنها مش زي بناتنا إللي عندهم تسع سنين، \nهي كانت امرأة بالغة تنفع للزواج، ومش معنى إنها كانت عالمرجيحة إنها كانت صغننة بقى وكده\nعادي يعني احنا أهه بنبقى معديين الثلاثين وبنروح نتمرجح\nوقصة زواج رسول الله ﷺ من السيدة عائشة وهي بنت تسع سنين موجودة في صحيح البخاري، \nثم أنا بستغرب بصراحة من الناس إللي بتقعد تقول إزاي رسول الله ﷺ يتزوج بنت صغيرة كده\nهو انتم يا جماعة معداش عليكم نساء قصيرات متزوجات من رجال طوال جدا، \nاشمعنى يعني عقلكم جايب دي ومش جايب دي\nده على افتراض يعني إن عائشة رضي الله عنها مكنتش امرأة طويلة بالغة تنفع تتزوج زي البنات إللي عندهم سبعة عشرة وثمانية عشرة سنة\nثم تعالوا هنا\n يعني المشركين واليهود أيام رسول الله ﷺ وإللي واقفين ومستنيين غلطة لرسول الله ﷺ عشان يشهّروا به ويعملوا مشكلة ويطعنوا في رسول الله والإسلام، \nهيفوتهم إنهم يتكلموا عن رسول الله ﷺ ويستنكروا إنه تزوج بطفلة\nده غير كده موضوع إن الرجل يتزوج امرأة وفارق السن بينهم كبير ده كان شيء عادي أيام الجاهلية،\nفالموضوع محتاج إننا نفهم الأمور بعصر رسول الله ﷺ وعقلية الناس إللي كانت عايشة فيه مش بعصرنا احنا\nوخدوا التقيلة بقى،\nعارفين الصحابي عمرو بن العاص\nخلف ابنه عبد الله لما عمرو نفسه كان عنده ثلاثة عشرة سنة،\nتخيلوا بقى كان متزوج وهو عنده كم سنة وزوجته عندها كم سنة\nفالمعايير في زمانهم غير المعايير في زماننا خالص\nمن الأحداث إللي حصلت برده في السنة الأولى من الهجرة، واحد من المسلمين خرج مهاجر من مكة للمدينة اسمه صُهيَب\nالرومي،\nمن أوائل المسلمين واحنا حكينا قصته قبل كده، وقلنا أد إيه كان ماهر وبارع لدرجة إن سيده أعتقه وبقى غني،\nفلما جه عشان يهاجر خبّى أمواله في مكان وطلع في الليل مهاجر،\nفشافه ناس من أهل مكة وطلعوا يجروا وراه عشان يمسكوه،\nفوقف وقال لهم: إنتم عارفين مهارتي في رمي السهام، وإن كل سهم هرميه هقتل منكم واحد\nفقالوا له : إنت جيت لنا فقير صعلوك معندكش أي مال، ولما بقى عندك فلوس عايز تاخد أموالنا وتهرب \nفقال لهم: يعني لو أنا أعطيكم الفلوس تسبوني أمشي\nفقالوا له : أه هنسيبك\nفقال لهم : طيب عارفين مكان كذا وكذا، روحوا احفروا هتلاقوا أموالي كلها هناك\nفسابوه وراحوا حفروا وطلعوا الأموال وأخذوها\nلما وصل الخبر لرسول الله ﷺ قال عن صهيب :\nربح البيع أبا يحيى، ربح البيع أبا يحيى.\nونزلت فيه:\n\"وَمِنَ النَّاسِ مَنْ يَشْرِي نَفْسَهُ ابْتِغَاءَ مَرْضَاتِ اللَّهِ وَاللَّهُ رَءُوفٌ بِالْعِبَادِ\"\n☆القصة دي عجيبة والله\nيعني هو كان ممكن يكذب عن مكان المال وهو يهرب وهم مع نفسهم،\nوده حقه أصلا لأن ده ماله، ومع ذلك تنازل عن ماله كله كده في لحظة\nلا وهم صدقوه وسابوه يمشي، يعني لم يشكّوا فيه للحظة\nمش عايز أقول لكم محتاجين نرجع أخلاق الجاهلية، لأ خلينا نلتزم بأخلاق الإسلام،\nكل واحد يركز على نفسه، كل واحد يبدأ بنفسه زي ما بنبدأ بنفسنا في تسوية صفوف الصلاة\nمن الأحداث إللي حصلت إن اليهود قالوا من باب الفتنة بين المسلمين إنهم سحروا المهاجرين فمبقاش يُولد لهم مولود ذكر\nلحد ما جاءت أسماء بنت أبي بكر الصديق رضي الله عنها وكانت حامل، فلما وصلت قباء ولدت عبد الله بن الزبير، فذهبت به لرسول الله ﷺ ووضعته في حجره وطلب تمرة ثم مضغها وحنك فم عبد الله بالتمرة ودعا له،\nوكان عبد الله بن الزبير هو أول مولود يولد للمسلمين في المدينة بعد الهجرة،\nوفرح الصحابة به فرح شديد لدرجة إنهم أخذوه وحملوه وقعدوا يكبروا\nفكان عبد الله بن الزبير أو مولود للمهاجرين بعد الهجرة، وكان النُّعمان بن بشير هو أول مولود للأنصار بعد الهجرة \nفي السنة الأولى من الهجرة زِيدت الصلاة،\nيعني احنا عندنا خمس صلوات مفروضين من أيام الإسراء والمعراج كل صلاة ركعتين،\nدلوقتي عدد الركعات نفسها هتزيد، يعني الظهر والعصر والعشاء هيبقوا أربع ركعات والمغرب ثلاثة لكن الصبح هيفضل ركعتين زي ما هو \nطيب إزاي المسلمين هيجتمعوا للصلاة\nبدأ المسلمون يتشاوروا ،فريق قال:\nنحط راية لما ييجي وقت الصلاة والناس تقول لبعضها، في ناس قالت طيب نستعمل البوق، وكان اليهود بينادوا يه لصلاتهم،\nفكرهه رسول الله ﷺ، \nفقالوا ممكن نستعمل الناقوس، جرس النصارى يعني، فكرهه برده رسول الله ﷺ، \nفقام واحد من الصحابة اسمه عبد الله بن زيد ومشي وهو عمال يفكر في حل،\nفلما رجع بيته ونام شاف رؤيا، والرؤيا كانت إن في رجل بيقول له لما يأتي وقت الصلاة قل:\nالله أكبر الله أكبر ....إلى نهاية الأذان، فصحِي من النوم وراح لرسول الله ﷺ وحكى له على الرؤيا فاستبشر بها رسول الله وقال له إنها لرؤيا حق\nوقال له علمها لبلال فهو صوته أحلى من صوتك،\nفلما أذن بلال سمعه عمر بن الخطاب وجاء لرسول الله ﷺ  وقال له والله يارسول الله أنا شفت الأذان ده في رؤيا رأيتها\nفقال له رسول الله ﷺ  : الحمد لله.\nوبقى الأذان المعروف هو النداء للصلاة\nمن الأحداث إللي حصلت إرسال رسول الله ﷺ حمزة بن عبد المطلب في سرية من المهاجرين عشان يرصدوا قافلة لقريش،\nإيه إللي حصل مع السرية وهل نجحت في مهمتها ولّا لأ،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 80, "l": "الجزء 54 | أول سرايا في الإسلام", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الرابعة_والخمسون\n#أول_سرايا_في_الإسلام\nكنا واقفين عند رسول الله ﷺ لما أرسل أول سرية في الإسلام عشان تعترض قافلة من قوافل قريش،\nلكن قبل ما نعرف الأحداث إللي حصلت في السرية دي خلونا نشوف بعض المواقف إللي حصلت مع رسول الله ﷺ في المدينة بصفة عامة\nمن المواقف دي موقف حصل مع رسول الله ﷺ ومع عبد الله بن أُبي بن سلول،\nكان سعد بن عبادة سيد الخزرج مريض فركب رسول الله ﷺ على حمار وكان مركّب خلفه أسامة بن زيد بن حارثة،\nوراح يزور سعد في بيته،\nوكان رسول الله ﷺ ميشوفش أي مجموعة من الناس إلا ويعرض عليهم الإسلام،\nفوهو ماشي عدى على مجموعة قاعدة وكانت المجموعة دي خليط من المسلمين والمشركين واليهود،\nوكان فيهم عبد الله بن رواحة المسلم وكان من الخزرج، وكان فيهم عبد الله بن أُبي بن سلول المشرك وكان سيد من سادات الخزرج،\nفالحمار لما بيمشي في أرض ترابية بيعمل زي غبار في الجو،\nفعبد الله بن أبي بن سلول قال بغضب:\nلا تُغبّروا علينا \nيعني متعفروش علينا بالتراب، وكان واضح إن الكلام فيه حدة وغضب،\nومع ذلك رسول الله ﷺ  مردش عليه، ونزل من على الحمار وراح عشان يدعوهم للإسلام، وقرأ عليهم القرآن،\nفقال عبد الله بن أبي ابن سلول وهو بيغلي من الغضب: \nأيها الرجل! هو مفيش أحسن من الكلام بتاعك ده لو كان حق فعلا\nفمتجيش تؤذينا بكلامك ده في مجالسنا، وارجع لبيتك وإللي يجيلك ابقى ادعيه زي مانت عايز\nفوقف عبد الله بن رواحة رضي الله عنه يدافع عن رسول اللهﷺ قال: \nلا يا رسول الله، تعال وكلمنا في مجالسنا زي مانت عايز فاحنا بنحب كده\n \n يعني عبد الله بن رواحة بيقول كلام عكس كلام عبد الله بن أبي بن سلول تماماً \nمع إنه من نفس قبيلته وهو صغير في السن وعبد الله بن أبي سيد في قومه ، لكن بالنسبة لعبد الله بن رواحة رسول الله ﷺ  أهم من أي شيء\nفالمسلمين والمشركين قعدوا يشتموا بعض وكل فريق بقى يناصر صاحبه،\nفمجموعة المسلمين كانت مع عبد الله بن رواحة، ومجموعة المشركين كانت مع عبد الله بن أبي بن سلول،\nوالمشكلة كبرت لدرجة إنهم رفعوا السيوف على بعض ورسول الله ﷺ واقف بينهم،\nفقعد رسول الله ﷺ يهدّي فيهم ويسكنهم لحد ما هدأوا،\nوأخذ اسامة وراح لسعد بن عبادة،\nفلما وصل عنده حكى له إللي حصل وقال له : لو شفت إللي عمله أبو حُباب، يعني عبد الله بن أبي بن سلول،\nفقال له سعد :\nمتزعلش يا رسول الله، أصل إنت مش متخيل القهرة إللي هو فيها،\nده كان خلاص الناس كانت خيّطت له التاج وكان هيبقى حاكم المدينة، وبعدين فجأة كل حاجة اتغيرت وبقيت أنت الحاكم،\nوكمان هو لسه مسمعش القرآن ولا يعرف حاجة عن الإسلام، لعله مع الوقت قلبه يلين\nفعفا عنه رسول الله ﷺ.\nنرجع لرسول الله ﷺ ونشوف موضوع السّرية إللي عقد لوائها لعمه حمزة بن عبد المطلب، \n لكن في البداية محتاجين نفهم هو ليه رسول الله ﷺ أرسل السرية دي، مش المسلمين كانوا مأمورين بالإعراض عن المشركين\n\"وَأَعْرِضْ عَنِ الْمُشْرِكِينَ\" \nالأوضاع في المدينة وحول المدينة أصبحت شبه مستقرة،\nلكن قريش لها علاقات بالقبائل حول المدينة،\nفممكن يتحدوا ويهجموا على المسلمين هجوم مفاجئ، \nوالمسلمين دلوقتي وضعهم مختلف عن زمان ،مبقوش مستضعفين زي الأول وبقى عندهم كيان ودولة\nفلازم يحموا الدولة بتاعتهم دي،\nعشان كده ربنا أَذن لهم بقتال المشركين، مجرد إذن مش فرض، \n\"أُذِنَ لِلَّذِينَ يُقَاتَلُونَ بِأَنَّهُمْ ظُلِمُوا ۚ وَإِنَّ اللَّهَ عَلَىٰ نَصْرِهِمْ لَقَدِيرٌ \"\nفكان الإذن بالقتال عشان المسلمين يرفعوا عن أنفسهم الظلم إللي تعرضوا له في مكة،\nظلم في الجسد بالتعذيب وأخذ الأموال بغير حق، وطردهم للمسلمين من ديارهم،\nفالإذن بالقتال كان بداية لمرحلة جديدة في التعامل مع المشركين،\nلكن قوة المسلمين الناشئة وأعدادهم القليلة لا تسمح لهم بالهجوم على مكة\nيبقى الحل إنهم يهاجموا قوافل قريش إللي بتتجه للشام ولازم تعدي على طريق المدينة المنورة،\nلأن القوافل دي إللي بيحميها قوة عسكرية بسيطة فيقدر يواجهها المسلمون، \nوكمان هيكونوا قريبين من المدينة يرجعوا لها في أي وقت،\nلأن المشركين واليهود موجودين في المدينة،\nلو المسلمين بِعدوا شوية عن المدينة ممكن يعملوا انقلاب ولا حاجة\nوالقوافل دي مُحمّلة بالبضائع والأموال فيقدروا يسترجعوا ولو جزء بسيط من أموالهم إللي المشركين أخذوها ظلما\n☆ممكن حد يسأل سؤال ويقول طيب ما كده المسلمين بيهجموا على القوافل الآمنة من قريش\nكفار مكة والمسلمين في حالة حرب مُعلنة، وكل طرف يستحل دم ومال الطرف الثاني، وده الطبيعي في حالة الحرب،\nوالإسلام دين واقعي يرد القوة بالقوة، \nثم هم إللي ابتدوا وأخذوا أموال المسلمين وطردوهم\n\"وَلَمَنِ انتَصَرَ بَعْدَ ظُلْمِهِ فَأُولَٰئِكَ مَا عَلَيْهِم مِّن سَبِيلٍ ۩ إِنَّمَا السَّبِيلُ عَلَى الَّذِينَ يَظْلِمُونَ النَّاسَ وَيَبْغُونَ فِي الْأَرْضِ بِغَيْرِ الْحَقِّ ۚ أُولَٰئِكَ لَهُمْ عَذَابٌ أَلِيمٌ\"\nودي تعتبر عبادة جديدة، أول مرة المسلمين هيطلعوا يجاهدوا في سبيل الله\nالقتال دلوقتي مختلف، محتاجين نعرف احنا بنقاتل ليه، ولو حد فينا مات في المعركة وضعه هيكون إيه،\nطيب لو انتصر\nفبدأ رسول الله ﷺ يعلمهم العبادة الجديدة، عبادة الجهاد في سبيل الله، \nعلمهم إن القتال يكون في سبيل الله فقط، عشان كلمة الله تكون هي العُليا، مش عشان ينصر قائد، ولا ينصر بلد على بلد ولا عشان السلطة، ولا خوف من القائد ولا بيقاتل عشان متحمس لقضية ، القتال فقط في سبيل الله\nوهنلاقي دايما في القرآن كلمة الجهاد لازم بييجي معاها في سبيل الله،\n\"إِنَّ اللَّهَ اشْتَرَىٰ مِنَ الْمُؤْمِنِينَ أَنفُسَهُمْ وَأَمْوَالَهُم بِأَنَّ لَهُمُ الْجَنَّةَ ۚ يُقَاتِلُونَ فِي سَبِيلِ اللَّهِ فَيَقْتُلُونَ وَيُقْتَلُونَ\"\nحتى في أعرابي بعدين جاء لرسول الله ﷺ وسأله :\n\" يَا رسولَ اللهِ؛ الرَّجُلُ يُقَاتِلُ لِلْمَغْنَمِ، وَالرَّجُلُ يُقَاتِلُ لِيُذْكَرَ، وَالرَّجُلُ يُقَاتِلُ ليُرَى مَكَانُهُ؟ \nوفي رواية: يُقَاتِلُ شَجَاعَةً وَيُقَاتِلُ حَمِيَّةً ـ\nوفي رواية: وَيُقَاتِلُ غَضَباً، فَمَنْ في سبيل الله؟\nفقالَ رسولُ اللهِ: مَنْ قَاتَلَ لِتَكُونَ كَلِمَةُ اللهِ هِيَ العُلْيَا، فَهُوَ في سَبيلِ اللهِ.\"\nيبقى الهدف بتاعنا واضح، جهاد في سبيل الله، لرفع الظلم الواقع على المسلمين\nوزي ما اتعودنا من رسول الله ﷺ ميعملش حاجة إلا بتخطيط وترتيب\nاختار رسول الله ﷺ المهاجرين عشان يطلعوا في السرايا إللي هيرسلها لمهاجمة قوافل قريش، والسبب في اختيار المهاجرين إنهم :\n◇أولا :\nعشان يثبتوا للجميع إن الحرب مش حرب قبلية، يعني مش إن قبيلة بتهجم على قبيلة تانية زي قبل الإسلام\n◇ثانيا:\nالمهاجرون هم إللي وقع عليهم الظلم من قريش، فحربهم مع قريش هتبقى حرب مفهومة عند كل أهل الجزيرة العربية، فهيعذروا المسلمين في حربهم ضد قريش، \nوبكده محدش هيفهم صورة الإسلام بطريقة خاطئة \n◇ثالثا:\n المهاجرون هيكونوا أكثر حمِية وأشد قوة في حربهم مع قريش؛ لأنهم بيحاولوا يسترجعوا حقهم إللي قريش أخذته منهم ظلما وعدوانا\n◇رابعا:\nالمهاجرون يعرفوا أهل قريش، ويعرفوا طُرق حربهم وطُرق قتالهم، لأنهم عاشوا معاهم فترة طويلة جدا، وعارفين القادة، وعارفين إمكانياتهم العسكرية بكل التفاصيل، وبالتالي فرصتهم في النصر أكبر \n◇خامسا:\n رسول الله ﷺ  محبش إنه يحرج الأنصار بإنه يطلب منهم الخروج للقتال ضد قريش خارج المدينة؛\n لأن الأنصار لما بايعوا بيعة العقبة الثانية بايعوا على أن ينصروا رسول الله ﷺ داخل المدينة المنورة لما يهاجر لهم، ولم يبايعوه على الحرب خارج المدينة،\nهو لو أمرهم مش هيعترضوا ولا هيرفضوا أمره، لكن هو مش عايز يسبب لهم الإحراج، فهو كان وفياً في كل عهوده، مش بيحرج حد عشان يعمل له إللي هو عايزه ﷺ \nأول لواء أو أول راية عَقدها رسول الله ﷺ في الإسلام كان لعمه حمزة بن عبد المطلب، وكان لونها أبيض في شهر رمضان من السنة الأولى للهجرة، \n☆ملحوظة: لحد دلوقتي لم يُفرض على المسلمين صيام شهر رمضان.\nأرسل رسول الله ﷺ مع حمزة ثلاثين رجل عشان يعترضوا قوافلة من قوافل قريش،\nوكان على رأس القافلة دي أبو جهل ومعاه ثلاثمائة رجل في القافلة،\nوخرجت السرية من المدية لحد ما وصلوا سِيف البحر أو ساحل البحر، فتقابل الفريقان\nلكن قبل ما يحصل أي اشتباك بينهم تدخل واحد اسمه مجديُّ بن عمرو الجُهَني وكان حليف من حلفاء قريش،\nوكان عامل معاهدة مع رسول الله ﷺ،\nوقف بينهم وقال لهم : ميحصلش قتال في أرضي، ومنع القتال بين الفريقين، ورجع حمزة للمدينة ورجع أبو جهل لمكة،\nهو أه المسلمين مقدروش يغنموا من القافلة دي، لكن الكفار وصل لهم رسالة مهمة\nوهي إن المهاجرين إللي خرجوا من مكة هربانين مضطهدين مش ضعفاء ولا منكسرين،\nدول أقوياء ومش هيسيبوهم، ولازم يعملوا لهم ألف حساب قبل ما يفكروا في مواجهتهم\nبعدها بشهر، وتحديدا في شهر شوال جهز رسول الله ﷺ سرية بقيادة الصحابي عُبيْدة بن الحارث بن عبد المطلب ومعاه ستين صحابي كلهم من المهاجرين عشان يعترضوا قافلة ثانية من قوافل قريش،\nوالقافلة المرة دي كان قائدها أبو سفيان بن حرب ومعاه مائتين رجل في القافلة،\nومحصلش بينهم أي قتال فقط مناوشات، وكان سعد بن أبي وقاص موجود في السرية فرمى القافلة بسهم، وكان هو أول من رمى بسهم في سبيل الله،\nواستطاعت القافلة إنها تهرب من غير ما يغنم منها المسلمون شيء،\nوحصلت كمان سريتين وأربع غزوات، هنتكلم عنهم المرة الجاية إن شاء الله \n☆"}, {"n": 81, "l": "الجزء 55 | السرايا والغزوات بعد الهجره", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_الخامسة_والخمسون\n#السرايا_والغزوات_بعد_الهجرة\nاتكلمنا المرة إللي فاتت عن السرايا إللي أرسلها رسول الله ﷺ حول المدين وقلنا أسباب السرايا دي كانت إيه،\nوقلنا إن السرايا إللي خرجت كانت كلها من المهاجرين ومكنش فيهم أي واحد من الأنصار وشرحنا السبب لو تفتكروا\nاتكلمنا عن سرية سِيف البحر بقيادة حمزة بن عبد المطلب وإللي كانت في رمضان من السنة الأولى للهجرة، \nوعن سرية رابِغ بقيادة عُبيدة بن الحارث في شهر شوال من نفس السنة،\nفي السنة الأولى للهجرة مات رجل من أعداء الإسلام،\nمات الوليد بن المغيرة، صاحب المقولة المشهورة عن القرآن :\nإن له لحلاوة وإن عليه لطلاوة...مات على الكفر، فهو خالد مخلد في النار\nفي شهر ذي القعدة عَقد رسول الله ﷺ لواء لسعد بن أبي وقّاص وأرسل معه عشرين من الصحابة المهاجرين لمنطقة الخرّار عشان يرصدوا قافلة من قوافل قريش، \nوأخذ عليهم العهد إنهم لا يتجاوزوا منطقة الخرّار، وكانوا بيمشوا بالليل ويختبئوا ويعملوا كمين بالنهار،\nلحد ما وصلوا المكان المتفق عليه لقوا القافلة كانت خلاص عدت من امبارح،\nعدّى شهر ذو الحجة وشهر محرم من غير أي سرايا لأنها أشهر حُرُم مفيهاش قتال،\nوطبعا السرية إللي طلعت في ذي القعدة محصلش فيها قتال، لأن ذو القعدة برده من الأشهر الحرم\nتقدروا تقولوا إن السرية إللي كانت في ذي القعدة كانت سرية استكشافية كده، أو تدريبية \nخلال الشهرين دول رسول الله ﷺ كان بيربي الصحابة إيمانيا، التربية الإيمانية موقفتش ومستمرة معانا على طول،\nلما كنا في مكة كانت الآيات إللي بتنزل على رسول الله ﷺ تتميز بإنها آيات قصيرة وتحدي للمشركين وشرح التوحيد وترسيخ الإيمان في قلوب الصحابة وكان الخطاب فيها \nب : يا أيها الناس، \nوتسمى الآيات والسور إللي نزلت في مكة طول الثلاثة عشرة سنة إللي فاتت بالسور المكية،\nأما دلوقتي فاحنا دخلنا في مرحلة جديدة مرحلة هيركز فيها القرآن على توحيد الألوهية\nوتوحيد الألوهية احنا شرحناه قبل كده في قصص الأنبياء ،\nفهو بكل بساطة معناه إن الحكم والتشريع بتاع ربنا،\nيعني الإنسان ميعملش أي حاجة غير لما يشوف حكم ربنا فيها إيه،\nوهي دي العبودية الحقيقية لله ومعنى لا إله إلا الله إللي بنقولها على طول\nفي الفترة المدنية هنلاقي إن عدد سور القرآن أقل من السور إللي نزلت في مكة،\nاحنا عارفين إن القرآن فيه مائة وأربعة عشرة سورة،  في منهم بقى ستة وثمانون سورة مكية،\nوالثمانية والعشرون الباقية مدنية، فهنلاقي إن أحاديث رسول الله ﷺ في الفترة المدنية كثيرة أكثر منها في فترة مكة\nيبقى كده القرآن هيركز للمؤمنين على التشريعات والأحكام،\nورسول الله ﷺ هيركز بأحاديثه على التربية الإيمانية،\nوطبعا كله وحي من عند ربنا،\nيعني القرآن والسنة بيكملوا بعض، وجهان لعملة واحدة، مينفعش ناخد القرآن من غير السنة ولا ناخد السنة من غير القرآن\nوعلى فكرة زي ما ربنا حفظ القرآن من التحريف فهو برده حَفِظ السّنة من التحريف\nمش ربنا بيقول :\n\"إِنَّا نَحْنُ نَزَّلْنَا الذِّكْرَ وَإِنَّا لَهُ لَحَافِظُونَ \"\nطيب ماهو لو كان المقصود بحفظ الذكر إللي هو القرآن فقط يبقى كده الدين هيبقى ناقص، \nلأن شرح القرآن كله موجود في حياة رسول الله ﷺ والأحداث إللي حصلت في حياته،\nفتخيلوا لو تم تحريف السنة أو لم تصلنا السنة من الأساس مكنش هيبقى في دين أصلا\n \n☆طيب أنا بقول لكم الكلام ده ليه \n لأن في ناس بتشكك في السّنة وفي ناس تانية بينكروها خالص بقى\n وبيقولوا احنا بس ناخد الموجود في القرآن واحنا إيه إللي يعرفنا إن الرسول قال الكلام ده، مش يمكن الكلام مش صحيح \nوالناس دي والله لو عندهم ذرة عقل وقرأوا القرآن كانوا هيلاقوا ربنا بيقول لهم:\n\"وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانتَهُوا\"\nفإزاي ربنا بيقول اعملوا إللي الرسول بيقول لكم عليه ومتعملوش إللي نهاكم عنه ومفيش سنّة\nشوفوا رسول الله ﷺ اتكلم عن الناس دي من ألف وأربعمائة سنة وقال إيه عنهم ووصفهم إزاي\n\"يُوشك أن يقعد الرجل متكئاً على أريكته يُحدث بحديث من حديثي فيقول :\nبيننا وبينكم كتاب الله ، فما وجدنا فيه من حلال استحللناه ، وما وجدنا فيه من حرام حرمناه ،\n ألا وإن ما حرم رسول الله مثل ما حرم الله\"\nفأنا عايزاكم تفهموا وتحفظوا الكلام ده كويس عشان لو حصل وقابلتوا حد من الناس دي تعرفوا تردوا وتدافعوا عن سنة نبيكم وتبقوا فخورين لما تقابلوه يوم القيامة على الحوض\nمن التربية الإيمانية إن رسول الله ﷺ كان بيصوم ثلاثة أيام من كل شهر وطبعا الصحابة كانوا بيقلدوه في كل حاجة\nوالصوم أصلا لوحده يعتبر مدرسة تربوية لوحده\nفهو :\n◇بيعود المسلم مراقبة الله، \nيبقى هيموت من العطش ولوحده محدش شايفه والمية قصاده حلال وميقدرش يشرب لأنه عارف إن ربنا يراه ولو فطر مش هياخد الأجر\n◇يقوّي عزيمة المسلم ويعوده على التحمل والصبر والتحكم في تصرفاته ورغباته،\nتخيلوا واحد ماسك نفسه عن الأكل والشرب ومتحكم فيها،\nمش هيقدر يمنع نفسه ويتحكم فيها لما تأمره بمعصية \nوبجانب الصيام كانت الصلوات الخمس مع رسول الله ﷺ وقراءة القرآن والكلام مع رسول الله ﷺ وغيرها من العبادات،\nكل ده من التربية الإيمانية، عدى الشهرين ذو الحِجة ومحرم،\nودخلنا في شهر صفر من السنة الثانية للهجرة،\nرسول الله ﷺ كان بيربي الصحابة تربية إيمانية خلال الشهرين إللي فاتوا لكنه برده متابع لأخبار مكة وقوافلها، فخرج بنفسه ومعاه ستين صحابي من المهاجرين وكان منهم عمه حمزة بن عبد المطلب،\n وهو حامل لواء أو راية المسلمين، وترك سعد بن عبادة يحكم المدينة لحد ما يرجع،\nواتجه رسول الله ﷺ  ناحية مكان اسمه الأَبْواء وهو بعيد عن المدينة حوالي مائتين وخمسين كيلو،\nهدفه إنه يعترض قافلة من قوافل قريش، لكن ملحقش القافلة وكانت عدت،\nلكنه تقابل مع قبيلة اسمها بني ضُمْرة، فعقد رسول الله ﷺ  معاهم صُلْح،\n☆ممكن حد يسأل هو رسول الله ﷺ مكنش بيتضايق لما يقطع المسافة دي كلها على الفرس أو الجمال وبعدين يرجع كده من غير ما يحقق هدفه\nلو فكرنا فيها بعقلنا هنلاقي إن الموضوع فعلا صعب ومحبط\n تخيلوا ناس خارجين في صحراء في شهر يونيو قعدوا في الطريق خمسة عشرة يوم وليلة رايح جاي وفي الآخر محققش إللي هو كان عايزه\nيعني الواحد مننا ممكن يروح يخلص ورق مثلا وبيركب تاكسي ولا أي وداخل مبنى، ويقعد رايح جاي، ولو الورق مخلصش بيبقى خلاص مش طايق نفسه، فتخيلوا موقف رسول الله ﷺ عامل إزاي\nلكن رسول الله ﷺ مكنش بيفكر كده، رسول الله ﷺ بيستغل كل حدث لمصلحته\nهو أه مقدرش يحصل على القافلة بس في مميزات تانية\n◇رسول الله ﷺ استكشف حول المدينة وعرف الطرق إللي بتؤدي لمكة،\n◇عقد معاهدة صلح مع القبائل الموجودة حول المدينة،\n◇رسالة عملية للمشركين في المدينة ولليهود وللأعراب إن المسلمين أقوياء وتخلصوا من ضعفهم القديم،\n◇إنذار لقريش إن تجارتها في خطر، فيمكن تخاف وتعقد صُلح مع رسول الله ﷺ وتترك المسلمين في حالهم،\n☆وده يعلمنا إننا حتى لو محققناش الهدف الرئيسي بتاعنا فأكيد هنحقق مكاسب تانية ولو كانت بسيطة أو بعيدة عن الهدف بتاعنا\nفي الشهر إللي بعده شهر ربيع الأول خرج رسول الله ﷺ مع مجموعة من أصحابه حوالي مائتين،\nوكان حامل لواء المسلمين هو سعد بن أبي وقاص، واستخلف سعد بن معاذ على حكم المدينة حتى يرجع،\n☆واللواء معناه راية الجيش، عارفين زي علم كده \nوكانت الراية مهمة جدا في المعارك ،\n لأن المسلمين بيعرفوا تحركات القادة منها،\nوطول ما الراية دي لسه واقفة معناه إن الجيش متماسك لو الراية سقطت معناه هزيمة الجيش وتنهار معنويات الجنود\nوصل رسول الله ﷺ لمنطقة اسمها بُوَاط عشان يعترضوا قافلة لقريش كان قائدها أمية بن خلف ومعاه مائة رجل من قريش والقافلة مكونة من ألفين وخمسمائة بعير، \nفلو غنمها المسلمون هتبقى ضربة جامدة لقريش ومكسب عظيم لهم،\nلكن رسول الله ﷺ ملحقهاش لأن جواسيس قريش عرفوا بخروج المسلمين فمشيوا من طريق تاني وعرفوا يهربوا، ورجع رسول الله ﷺ للمدينة، وسميت الغزوة دي بغزوة بُواط،\n☆طيب ليه ربنا مأنزلش الوحي على رسول الله ﷺ يقول له مكان القافلة وكان يقدر يلحقهم\n لأن رسول الله ﷺ قدوة زي ما قلنا قبل كده، فلازم يستعمل الطرق البشرية عشان إللي هييجي بعده يعرف يتصرف إزاي\nفي شهر جمادى الأولى خرج رسول الله ﷺ في غزوة ثالثة ومعاه مائة وخمسين من أصحابه،  ورسول الله ﷺ مكنش بيُرغم أحد على الخروج معاه،\nيعني هو كان يقول أنا طالع كذا مين يأتي معي فكان بيخرج معاه الصحابة على حسب رغبتهم، يعني مكنش أمر إلزامي بالخروج\nفخرج عشان يعترض قافلة من قوافل قريش، وكان معاه حمزة بن عبد المطلب وكان هو حامل لواء رسول الله ﷺ، فلما وصل لمنطقة اسمها العُشَيرة لقبيلة بني مدلج كانت القافلة هربت،\nفحصل بين رسول الله ﷺ وبين قبيلة بني مدلج معاهدة صلح، وجلس رسول الله ﷺ في المكان ده لحد آخر الشهر وبعدين رجع للمدينة،\nبعدها بعشرة أيام هجم واحد اسمه كِرْز بن جابر الفهري على أطراف المدينة، المكان إللي فيه المواشي،\nفلما وصل الخبر لرسول الله ﷺ قام بسرعة وأخذ فرسه وانطلق وراه عشان يجيبه\nوفضل رسول الله ﷺ يطارده لحد ما وصلوا لمكان اسمه وادي سَفْوان قريب من بدر،\nوعرف كِرز بن جابر إنه يهرب من رسول الله ﷺ، ورجع رسول الله ﷺ للمدينة، و أسلم كِرز بن جابر الفهري بعدين\nوكانت دي غزوة سَفوان أو غزوة بدر الأولى،\n☆في علماء قالوا إن غزوة سَفوان كانت قبل غزوة العُشَيرة،\nفمش هتفرق كتير إللي يهمنا إن الغزوتين حصلوا\nدخلنا في شهر رجب وهو من الأشهر الحُرم فمفيش فيه قتال،\nفي أواخر رجب أرسل رسول الله ﷺ ثمانية من الصحابة المهاجرين ويقال كانوا اثنا عشر في سرية وكان قائدهم عبد الله بن جحش بن عمة رسول الله ﷺ، \n☆الفرق بين الغزوة والسرية، إن الغزوة مجموعة عسكرية قائدهم فيها رسول الله ﷺ، \nلكن السرية المجوعة العسكرية إللي بتخرج رسول الله ﷺ مش بيكون معاهم فيها\nكان في من ضمن السرية دي عُكّاشة بن مِحْصن وعتبة بن غزوان وسعد بن أبي وقاص خال النبي ﷺ،\nوالمقصود بخال النبي يعني هو من أبناء عم أمه، فيقال عليه خاله،\nالمهم رسول الله ﷺ أعطى لعبد الله بن جحش كتاب مقفول، رسالة يعني\nوقال له بعد ما تمشي مسافة يومين افتح الكتاب واقرأه وبعدين نفذ إللي فيه،\nفبعد ما عدى اليومين فتح الكتاب لقى فيه:\nأول ما تشوف كتابي روح لحد ما توصل وادي نخلة بين مكة والطائف، وتراقب لنا قريش وتعرف أخبارهم وبعدين ترجع،\n☆فاكرييين وادي نخلة\nلما كان رسول الله ﷺ راجع من الطائف ووقف يصلي ركعتين إيه إللي حصل\nالجن إللي سمعوا رسول الله ﷺ بيقرأ القرآن وأسلموا ورجعوا يدعوا قومهم\nبعد ما قرأ عبد الله بن جحش الكتاب قال :سمعاً وطاعة،\nوأخبر أصحابه بكلام رسول الله ﷺ وقال لهم إن رسول الله نهاه إنه يرغم أحد منهم إنه يروح معاه،\nيعني إللي مش عايز يكمل المهمة عادي ممكن يرجع، فكلهم كملوا\nوهم ماشيين ضاع منهم بعير، فراح سعد بن أبي وقاص وعتبة بن غزوان يدوروا عليه، وكمل الستة الطريق لوادي نخلة،\nفلما وصلوا عدت عليهم عِير قريش وكان فيهم واحد اسمه عمرو بن الحَضْرَمي،\nفلما الناس إللي في القافلة شافوا المسلمين خافوا منهم، وكان عكاشة بن محصن لسه حالق شعره، يعني مفيش ولا شعرة في رأسه، فقالوا بيطمنوا بعض :\n متقلقوش منهم دول كانوا جايين للعمرة\nفاجتمع الصحابة وقعدوا يتشاوروا مع بعض وقالوا :\nلو سيبناهم الليلة دي هيدخلوا مكة ومش هتقدروا عليهم،\nولو قتلناهم يبقى احنا هنقتلهم في الشهر الحرام\nوالكلام ده كان آخر يوم في رجب،\nوالقافلة دي تعتبر مهمة جدا لأنها هتكون أول ضربة قوية لقريش،\nاحنا شفنا السرايا والغزوات إللي فاتت مكنش فيها أي غنائم، \nوكمان دي فرصة لأن القافلة دي مكنش فيها غير أربعة فقط،\nده غير إنها مكان القتال قريب منهم جدا وبعيد عن المدينة،\nيعني احنا جينا ضربناكم في عُقر داركم\nوده في مصلحة المسلمين أكيد\nفضلوا مترددين شوية وخافوا يهجموا عليهم، وبعدين اتشجعوا وهجموا على القافلة فقتلوا عمرو بن الحضرمي، وأخذوا أسيرين معاهم هما عثمان بن عبد الله والحكم بن كَيّسان والرابع عرف يهرب ،\nأخذ المسلمون الغنائم والأسيرين ورجعوا للمدينة، فلما وصلوا لرسول الله ﷺ قال لهم:\nإنتم قاتلتم في الشهر الحرام؟!! أنا ما أمرتكم بالقتال في الشهر الحرام!!\nولم يأخذ رسول الله ﷺ الغنائم وخلى الأسيرين عنده لحد ما يشوف هيعمل إيه\nفخاف الصحابة وظنوا إنهم خلاص هلكوا ومبقوش عارفين يعملوا إيه\nوقريش طبعا ماصدقت\nمحمد وأصحابه استحلوا الأشهر الحرم، وسفكوا الدماء وأخذوا الأموال\n☆ده على أساس إن قريش ما شاء الله بريئة بقى ومكنتش بتعذب المسلمين وتقتلهم في البلد الحرام والشهر الحرام\n القتال في الأشهر الحرم حاجة كبيرة جدا عند العرب،\nيعني كان بيسموا الحرب إللي بتحصل في الأشهر الحرم حرب الفُجَار،\n يعني الناس فجرت في الأشهر الحرم،\nفدلوقتي مصدقوا بقى الغلطة دي حصلت منهم، ومسكوها لهم\nوالمسلمين إللي كانوا في مكة بقى يدافعوا ويقولوا ده كان في شعبان مكنش في رجب\nفربنا أنزل قرآن عشان ينهي الموضوع خالص قال تعالى:\n\"يَسْأَلُونَكَ عَنِ الشَّهْرِ الْحَرَامِ قِتَالٍ فِيهِ ۖ \nقُلْ قِتَالٌ فِيهِ كَبِيرٌ ۖ وَصَدٌّ عَن سَبِيلِ اللَّهِ وَكُفْرٌ بِهِ وَالْمَسْجِدِ الْحَرَامِ وَإِخْرَاجُ أَهْلِهِ مِنْهُ أَكْبَرُ عِندَ اللَّهِ ۚ وَالْفِتْنَةُ أَكْبَرُ مِنَ الْقَتْلِ \"\nيعني ربنا بيُقر إن مفيش قتال في الأشهر الحرم، لكن الصد عن سبيل الله والكفر به واضطهاد الضعفاء ،\nوإخراجهم من بيوتهم بغير حق أشد عند ربنا من القتال في الشهر الحرام،\nيعني إنتم عاملين فيها شرفاء أوي وزعلانين إن حصل قتال في الشهر الحرام، لأ إللي عملتوه مع المسلمين وفتنتهم عن دينهم أشد عند ربنا من القتال في الشهر الحرام\nففرج الله عن المسلمين واتحلت المشكلة وأخذ رسول الله ﷺ الغنائم،\nوبعثت قريش أموال عشان تفتدي الأسيرين،فرفض رسول الله ﷺ إنه يطلق سراحهما إلا لما يرجع سعد بن أبي وقاص وعتبة بن غزوان،\nراحوا يدوروا على البعير ومرجعوش لحد دلوقتي\nفخاف رسول الله ﷺ إن قريش يأسروهم ويقتلوهم، فقال لما يرجعوا الأول\nفلما رجعا أطلق رسول الله ﷺ سراح الأسيرين الكافرين،\nفأسلم الحكم بن كيّسان وحسن إسلامه،\nأما عثمان بن عبد الله فرجع مكة، وبعد ما رجع مات على الكفر، مع إن الإثنين كانوا في نفس الظروف واتعاملوا نفس المعاملة لكن سبحان من هدى هذا وأضل هذا\nوكانت دي أول سرية تغنم غنيمة في الإسلام، وأول قتيل في الإسلام\nسرية نخلة بتعلمنا الشورى وبتعلمنا السمع والطاعة المطلقة لرسول الله ﷺ، \nوبتعلمنا إننا لا ننتقم لأنفسنا وخلاص، كان بإمكان رسول الله ﷺ إنه يعذب الأسيرين، أو حتى يقتلهم ومحدش يقدر يلوم عليه بعد إللي قريش عملوه فيه وفي أصحابه،\nلكن هو اختار الرحمة والعفو و النتيجة إنه أنقذ روح من النار، وده أهم من الإنتقام للنفس\nقريش عدت الموضوع ظاهريا لكن مش بعيد ترد رد قاسي على المسلمين،\nهننتظر ونشوف الوضع هيوصل مع قريش لإيه،\nلكن قبل ما تعمل قريش أي حاجة حصل في المدينة حدث قلب الدنيا كلها \nإيه إللي حصل خلى المشركين واليهود يشمتوا في المسلمين؟\nده إللي هنعرفوا الجزء الجاي إن شاء الله"}]);
